var T={"en": {"name": "English", "nav.home": "Home", "nav.privacy": "Privacy", "nav.terms": "Terms", "nav.support": "Support", "home.tag": "Find your Bluetooth devices — nearby, or where you last had them.", "home.h": "What it does", "home.l1": "Remembers where you were when a device connects or disconnects, and shows it on a map.", "home.l2": "Keeps a 24-hour trail so you can retrace your steps.", "home.l3": "Guides you to a nearby device with signal strength, haptics, and optional AR / AirPods direction cues.", "home.l4": "<b>Everything stays on your iPhone.</b> No account, no upload, no analytics.", "priv.title": "Privacy Policy", "priv.h1": "Summary", "priv.p1": "Blueee does not collect, upload, sell or share any personal data. It has no accounts, no servers and no analytics or advertising SDKs. All data lives on your iPhone.", "priv.h2": "Data the app uses on your device", "priv.loc": "<b>Location</b> (including “Always” if you allow it): records where you were when a device connects or disconnects and keeps a 24-hour trail. Stored locally; older points are removed automatically.", "priv.ble": "<b>Bluetooth</b>: connects to devices you add, detects connect/disconnect in the background and reads signal strength. Device names and identifiers are stored locally.", "priv.cam": "<b>Camera</b> (“Walk to Locate”): ARKit tracks the route your phone walks. Images are processed live and are never photographed, saved or uploaded.", "priv.mot": "<b>Motion</b> (AirPods head tracking): read live to steer the audio cue; never saved or uploaded.", "priv.h3": "Sharing and retention", "priv.p3": "None of this data leaves your device, so we cannot access, share or sell it. Deleting the app deletes its data. You can revoke any permission in iOS Settings → Blueee.", "priv.h4": "Children", "priv.p4": "Blueee does not knowingly collect any data from anyone, including children.", "priv.h5": "Changes and contact", "priv.p5": "If this policy changes, the date below will be updated. Questions: open an issue at <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Terms of Use", "terms.h1": "Use of the app", "terms.p1": "Blueee is provided free of charge for personal use. By using it you agree to these terms. Apple’s standard Licensed Application End User License Agreement also applies.", "terms.h2": "No guarantee of finding a device", "terms.p2": "Location, Bluetooth signal strength and direction cues are estimates. They can be wrong or unavailable (for example when a device is off, out of range, or iOS limits background activity). Do not rely on Blueee for safety-critical or high-value tracking.", "terms.h3": "Acceptable use", "terms.p3": "Use Blueee only with devices you own or have permission to locate, never to track people, and follow local laws.", "terms.h4": "Warranty and liability", "terms.p4": "The app is provided “as is” without warranties. To the extent permitted by law, the developer is not liable for loss of or damage to any device or data arising from use of the app.", "terms.h5": "Changes", "terms.p5": "These terms may be updated; continued use means acceptance.", "sup.title": "Support", "sup.h1": "Get help", "sup.p1": "Open an issue at <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> with your iPhone model, iOS version and what happened.", "sup.h2": "FAQ", "sup.q1": "Why does it ask for “Always” location?", "sup.a1": "So it can record where you were the moment a device disconnects while the app is in the background. “While Using” also works but may miss background disconnects.", "sup.q2": "Is my data uploaded?", "sup.a2": "No. Everything stays on your iPhone. See the <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "A device is not detected in the background.", "sup.a3": "Make sure Bluetooth is on, Background App Refresh is allowed, and the app was not force-quit from the app switcher.", "foot": "© 2026 Blueee · Last updated 2026-11-09", "privacyLink": "Privacy Policy"}, "zh": {"name": "简体中文", "nav.home": "首页", "nav.privacy": "隐私", "nav.terms": "条款", "nav.support": "支持", "home.tag": "找到你的蓝牙设备：在身边就带你走过去，丢了就告诉你最后在哪。", "home.h": "功能", "home.l1": "设备连上或断开时记录你所在的位置，并显示在地图上。", "home.l2": "保留 24 小时轨迹，方便回头找。", "home.l3": "用信号强度、触感，以及可选的 AR / AirPods 方向提示，带你走到身边的设备。", "home.l4": "<b>所有数据只保存在你的 iPhone 上。</b>无账号、不上传、无统计。", "priv.title": "隐私政策", "priv.h1": "概述", "priv.p1": "Blueee 不收集、不上传、不出售、不分享任何个人数据。没有账号、没有服务器，也没有统计或广告 SDK。所有数据只保存在你的 iPhone 上。", "priv.h2": "App 在你设备上使用的数据", "priv.loc": "<b>位置</b>（如你允许“始终”）：记录设备连上或断开时你所在的位置，并保留 24 小时轨迹。仅存本机，过期自动清除。", "priv.ble": "<b>蓝牙</b>：连接你添加的设备、在后台感知连上/断开、读取信号强度。设备名称和标识仅存本机。", "priv.cam": "<b>相机</b>（“走一走定位”）：ARKit 跟踪手机走过的路线。画面实时处理，不拍照、不保存、不上传。", "priv.mot": "<b>运动</b>（AirPods 头部追踪）：实时读取用于调整声音方向，不保存、不上传。", "priv.h3": "分享与保留", "priv.p3": "这些数据不会离开你的设备，因此我们无法访问、分享或出售。删除 App 即删除全部数据；你可随时在 iOS 设置 → Blueee 中撤销权限。", "priv.h4": "儿童", "priv.p4": "Blueee 不会有意收集任何人（包括儿童）的数据。", "priv.h5": "变更与联系", "priv.p5": "政策变更时，下方日期会更新。有问题请到 <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> 提 issue。", "terms.title": "使用条款", "terms.h1": "使用说明", "terms.p1": "Blueee 免费提供，仅供个人使用。使用即表示你同意这些条款，同时适用 Apple 标准的最终用户许可协议。", "terms.h2": "不保证一定能找到设备", "terms.p2": "位置、蓝牙信号强度和方向提示都只是估计，设备关机、超出范围或 iOS 限制后台时可能不准或不可用。请勿用于安全关键或高价值的追踪。", "terms.h3": "合理使用", "terms.p3": "仅用于你自己的或已获许可的设备，不得用于追踪他人，并遵守当地法律。", "terms.h4": "免责声明", "terms.p4": "本 App 按“现状”提供，不作任何担保。在法律允许范围内，开发者对因使用本 App 造成的设备或数据损失不承担责任。", "terms.h5": "变更", "terms.p5": "条款可能更新，继续使用即视为接受。", "sup.title": "支持", "sup.h1": "获取帮助", "sup.p1": "请到 <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> 提 issue，写明 iPhone 型号、iOS 版本和遇到的问题。", "sup.h2": "常见问题", "sup.q1": "为什么要求“始终”位置？", "sup.a1": "为了在 App 处于后台时，设备断开的瞬间也能记下你的位置。选“使用期间”也能用，但可能漏掉后台断开。", "sup.q2": "数据会上传吗？", "sup.a2": "不会，全部保存在你的 iPhone 上。详见<a href=\"privacy.html\">Privacy Policy</a>。", "sup.q3": "后台检测不到设备。", "sup.a3": "请确认蓝牙已开启、允许“后台 App 刷新”，并且没有在多任务界面里强制退出 App。", "foot": "© 2026 Blueee · 最后更新 2026-11-09", "privacyLink": "隐私政策"}, "es": {"name": "Español", "nav.home": "Inicio", "nav.privacy": "Privacidad", "nav.terms": "Términos", "nav.support": "Soporte", "home.tag": "Encuentra tus dispositivos Bluetooth: cerca de ti, o donde los tuviste por última vez.", "home.h": "Qué hace", "home.l1": "Recuerda dónde estabas cuando un dispositivo se conecta o desconecta y lo muestra en un mapa.", "home.l2": "Guarda un recorrido de 24 horas para que puedas volver sobre tus pasos.", "home.l3": "Te guía hasta un dispositivo cercano con la intensidad de señal, la respuesta háptica y, opcionalmente, indicaciones de dirección con AR o AirPods.", "home.l4": "<b>Todo se queda en tu iPhone.</b> Sin cuenta, sin subir datos, sin analíticas.", "priv.title": "Política de privacidad", "priv.h1": "Resumen", "priv.p1": "Blueee no recopila, sube, vende ni comparte datos personales. No tiene cuentas, servidores ni SDK de analíticas o publicidad. Todos los datos están en tu iPhone.", "priv.h2": "Datos que la app usa en tu dispositivo", "priv.loc": "<b>Ubicación</b> (incluido “Siempre” si lo permites): registra dónde estabas cuando un dispositivo se conecta o desconecta y guarda un recorrido de 24 horas. Se almacena localmente; los puntos antiguos se eliminan automáticamente.", "priv.ble": "<b>Bluetooth</b>: se conecta a los dispositivos que añades, detecta conexiones y desconexiones en segundo plano y lee la intensidad de señal. Los nombres e identificadores se guardan localmente.", "priv.cam": "<b>Cámara</b> (“Camina para localizar”): ARKit sigue la ruta que recorre tu teléfono. Las imágenes se procesan en directo y nunca se fotografían, guardan ni suben.", "priv.mot": "<b>Movimiento</b> (seguimiento de cabeza de AirPods): se lee en directo para orientar el sonido; nunca se guarda ni se sube.", "priv.h3": "Compartir y conservación", "priv.p3": "Ninguno de estos datos sale de tu dispositivo, así que no podemos acceder a ellos, compartirlos ni venderlos. Al eliminar la app se eliminan sus datos. Puedes revocar cualquier permiso en Ajustes de iOS → Blueee.", "priv.h4": "Menores", "priv.p4": "Blueee no recopila a sabiendas datos de nadie, incluidos los menores.", "priv.h5": "Cambios y contacto", "priv.p5": "Si esta política cambia, se actualizará la fecha de abajo. Preguntas: abre una incidencia en <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Términos de uso", "terms.h1": "Uso de la app", "terms.p1": "Blueee se ofrece gratis para uso personal. Al usarla aceptas estos términos. También se aplica el Contrato de licencia estándar de Apple para aplicaciones con licencia.", "terms.h2": "Sin garantía de encontrar un dispositivo", "terms.p2": "La ubicación, la intensidad de señal Bluetooth y las indicaciones de dirección son estimaciones. Pueden ser incorrectas o no estar disponibles (por ejemplo, si el dispositivo está apagado, fuera de alcance o iOS limita la actividad en segundo plano). No dependas de Blueee para rastreos críticos o de alto valor.", "terms.h3": "Uso aceptable", "terms.p3": "Usa Blueee solo con dispositivos que sean tuyos o que tengas permiso para localizar, nunca para rastrear personas, y cumple las leyes locales.", "terms.h4": "Garantía y responsabilidad", "terms.p4": "La app se ofrece “tal cual”, sin garantías. En la medida permitida por la ley, el desarrollador no es responsable de la pérdida o el daño de dispositivos o datos derivados del uso de la app.", "terms.h5": "Cambios", "terms.p5": "Estos términos pueden actualizarse; seguir usando la app implica aceptarlos.", "sup.title": "Soporte", "sup.h1": "Obtener ayuda", "sup.p1": "Abre una incidencia en <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> indicando el modelo de iPhone, la versión de iOS y qué ocurrió.", "sup.h2": "Preguntas frecuentes", "sup.q1": "¿Por qué pide la ubicación “Siempre”?", "sup.a1": "Para poder registrar dónde estabas en el momento en que un dispositivo se desconecta mientras la app está en segundo plano. “Mientras se usa” también funciona, pero puede perder desconexiones en segundo plano.", "sup.q2": "¿Se suben mis datos?", "sup.a2": "No. Todo se queda en tu iPhone. Consulta la <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Un dispositivo no se detecta en segundo plano.", "sup.a3": "Comprueba que Bluetooth esté activado, que la actualización en segundo plano esté permitida y que no hayas forzado el cierre de la app desde el selector de apps.", "foot": "© 2026 Blueee · Última actualización: 2026-11-09", "privacyLink": "Política de privacidad"}, "fr": {"name": "Français", "nav.home": "Accueil", "nav.privacy": "Confidentialité", "nav.terms": "Conditions", "nav.support": "Assistance", "home.tag": "Retrouvez vos appareils Bluetooth : à proximité, ou là où vous les aviez en dernier.", "home.h": "Fonctionnalités", "home.l1": "Mémorise où vous étiez quand un appareil se connecte ou se déconnecte et l’affiche sur une carte.", "home.l2": "Conserve un parcours de 24 heures pour revenir sur vos pas.", "home.l3": "Vous guide vers un appareil proche grâce à la force du signal, aux retours haptiques et, en option, à des indications de direction en AR ou avec les AirPods.", "home.l4": "<b>Tout reste sur votre iPhone.</b> Pas de compte, pas d’envoi de données, pas de mesure d’audience.", "priv.title": "Politique de confidentialité", "priv.h1": "Résumé", "priv.p1": "Blueee ne collecte, n’envoie, ne vend ni ne partage aucune donnée personnelle. Il n’y a ni compte, ni serveur, ni SDK d’analyse ou de publicité. Toutes les données restent sur votre iPhone.", "priv.h2": "Données utilisées par l’app sur votre appareil", "priv.loc": "<b>Localisation</b> (y compris « Toujours » si vous l’autorisez) : enregistre où vous étiez quand un appareil se connecte ou se déconnecte et conserve un parcours de 24 heures. Stockée localement ; les anciens points sont supprimés automatiquement.", "priv.ble": "<b>Bluetooth</b> : se connecte aux appareils que vous ajoutez, détecte les connexions et déconnexions en arrière-plan et lit la force du signal. Les noms et identifiants sont stockés localement.", "priv.cam": "<b>Appareil photo</b> (« Marcher pour localiser ») : ARKit suit le trajet de votre téléphone. Les images sont traitées en direct et ne sont jamais photographiées, enregistrées ni envoyées.", "priv.mot": "<b>Mouvement</b> (suivi de la tête des AirPods) : lu en direct pour orienter le son ; jamais enregistré ni envoyé.", "priv.h3": "Partage et conservation", "priv.p3": "Aucune de ces données ne quitte votre appareil : nous ne pouvons donc ni y accéder, ni les partager, ni les vendre. Supprimer l’app supprime ses données. Vous pouvez révoquer toute autorisation dans Réglages iOS → Blueee.", "priv.h4": "Enfants", "priv.p4": "Blueee ne collecte sciemment aucune donnée, y compris celles des enfants.", "priv.h5": "Modifications et contact", "priv.p5": "Si cette politique change, la date ci-dessous sera mise à jour. Questions : ouvrez un ticket sur <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Conditions d’utilisation", "terms.h1": "Utilisation de l’app", "terms.p1": "Blueee est fournie gratuitement pour un usage personnel. En l’utilisant, vous acceptez ces conditions. Le contrat de licence standard d’Apple pour les apps sous licence s’applique également.", "terms.h2": "Aucune garantie de retrouver un appareil", "terms.p2": "La localisation, la force du signal Bluetooth et les indications de direction sont des estimations. Elles peuvent être inexactes ou indisponibles (appareil éteint, hors de portée, ou activité en arrière-plan limitée par iOS). Ne comptez pas sur Blueee pour un suivi critique ou de grande valeur.", "terms.h3": "Usage acceptable", "terms.p3": "Utilisez Blueee uniquement avec des appareils qui vous appartiennent ou que vous avez le droit de localiser, jamais pour suivre des personnes, et respectez la loi locale.", "terms.h4": "Garantie et responsabilité", "terms.p4": "L’app est fournie « telle quelle », sans garantie. Dans la limite permise par la loi, le développeur n’est pas responsable de la perte ou de l’endommagement d’un appareil ou de données liés à l’utilisation de l’app.", "terms.h5": "Modifications", "terms.p5": "Ces conditions peuvent être mises à jour ; continuer à utiliser l’app vaut acceptation.", "sup.title": "Assistance", "sup.h1": "Obtenir de l’aide", "sup.p1": "Ouvrez un ticket sur <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> en indiquant votre modèle d’iPhone, la version d’iOS et ce qui s’est passé.", "sup.h2": "FAQ", "sup.q1": "Pourquoi demande-t-elle la localisation « Toujours » ?", "sup.a1": "Pour enregistrer où vous étiez au moment où un appareil se déconnecte alors que l’app est en arrière-plan. « Lorsque l’app est active » fonctionne aussi, mais peut manquer des déconnexions en arrière-plan.", "sup.q2": "Mes données sont-elles envoyées ?", "sup.a2": "Non. Tout reste sur votre iPhone. Voir la <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Un appareil n’est pas détecté en arrière-plan.", "sup.a3": "Vérifiez que le Bluetooth est activé, que l’actualisation en arrière-plan est autorisée et que l’app n’a pas été fermée de force depuis le sélecteur d’apps.", "foot": "© 2026 Blueee · Dernière mise à jour : 2026-11-09", "privacyLink": "Politique de confidentialité"}, "pt": {"name": "Português", "nav.home": "Início", "nav.privacy": "Privacidade", "nav.terms": "Termos", "nav.support": "Suporte", "home.tag": "Encontre seus dispositivos Bluetooth: por perto, ou onde você os teve pela última vez.", "home.h": "O que faz", "home.l1": "Lembra onde você estava quando um dispositivo conecta ou desconecta e mostra isso em um mapa.", "home.l2": "Guarda um trajeto de 24 horas para você refazer seus passos.", "home.l3": "Guia você até um dispositivo próximo com a intensidade do sinal, resposta tátil e, opcionalmente, indicações de direção com AR ou AirPods.", "home.l4": "<b>Tudo fica no seu iPhone.</b> Sem conta, sem envio de dados, sem análises.", "priv.title": "Política de Privacidade", "priv.h1": "Resumo", "priv.p1": "O Blueee não coleta, envia, vende nem compartilha dados pessoais. Não há contas, servidores nem SDKs de análise ou publicidade. Todos os dados ficam no seu iPhone.", "priv.h2": "Dados que o app usa no seu dispositivo", "priv.loc": "<b>Localização</b> (incluindo “Sempre” se você permitir): registra onde você estava quando um dispositivo conecta ou desconecta e guarda um trajeto de 24 horas. Armazenada localmente; pontos antigos são removidos automaticamente.", "priv.ble": "<b>Bluetooth</b>: conecta aos dispositivos que você adiciona, detecta conexões e desconexões em segundo plano e lê a intensidade do sinal. Nomes e identificadores ficam armazenados localmente.", "priv.cam": "<b>Câmera</b> (“Andar para localizar”): o ARKit acompanha o trajeto do seu celular. As imagens são processadas na hora e nunca são fotografadas, salvas nem enviadas.", "priv.mot": "<b>Movimento</b> (rastreamento de cabeça dos AirPods): lido ao vivo para direcionar o som; nunca salvo nem enviado.", "priv.h3": "Compartilhamento e retenção", "priv.p3": "Nenhum desses dados sai do seu dispositivo, então não podemos acessá-los, compartilhá-los nem vendê-los. Excluir o app exclui seus dados. Você pode revogar qualquer permissão em Ajustes do iOS → Blueee.", "priv.h4": "Crianças", "priv.p4": "O Blueee não coleta conscientemente dados de ninguém, incluindo crianças.", "priv.h5": "Alterações e contato", "priv.p5": "Se esta política mudar, a data abaixo será atualizada. Dúvidas: abra uma issue em <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Termos de Uso", "terms.h1": "Uso do app", "terms.p1": "O Blueee é oferecido gratuitamente para uso pessoal. Ao usá-lo, você concorda com estes termos. O Contrato de Licença padrão da Apple para apps licenciados também se aplica.", "terms.h2": "Sem garantia de encontrar um dispositivo", "terms.p2": "Localização, intensidade do sinal Bluetooth e indicações de direção são estimativas. Podem estar erradas ou indisponíveis (por exemplo, com o dispositivo desligado, fora de alcance ou com o iOS limitando a atividade em segundo plano). Não dependa do Blueee para rastreamento crítico ou de alto valor.", "terms.h3": "Uso aceitável", "terms.p3": "Use o Blueee apenas com dispositivos seus ou que você tenha permissão para localizar, nunca para rastrear pessoas, e siga as leis locais.", "terms.h4": "Garantia e responsabilidade", "terms.p4": "O app é fornecido “como está”, sem garantias. Na medida permitida por lei, o desenvolvedor não se responsabiliza por perda ou dano a dispositivos ou dados decorrentes do uso do app.", "terms.h5": "Alterações", "terms.p5": "Estes termos podem ser atualizados; continuar usando significa aceitá-los.", "sup.title": "Suporte", "sup.h1": "Obter ajuda", "sup.p1": "Abra uma issue em <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> informando o modelo do iPhone, a versão do iOS e o que aconteceu.", "sup.h2": "Perguntas frequentes", "sup.q1": "Por que ele pede localização “Sempre”?", "sup.a1": "Para registrar onde você estava no momento em que um dispositivo desconecta com o app em segundo plano. “Ao usar o app” também funciona, mas pode perder desconexões em segundo plano.", "sup.q2": "Meus dados são enviados?", "sup.a2": "Não. Tudo fica no seu iPhone. Veja a <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Um dispositivo não é detectado em segundo plano.", "sup.a3": "Verifique se o Bluetooth está ligado, se a Atualização em Segundo Plano está permitida e se o app não foi fechado à força no seletor de apps.", "foot": "© 2026 Blueee · Última atualização: 2026-11-09", "privacyLink": "Política de Privacidade"}, "ru": {"name": "Русский", "nav.home": "Главная", "nav.privacy": "Конфиденциальность", "nav.terms": "Условия", "nav.support": "Поддержка", "home.tag": "Находите свои Bluetooth-устройства: рядом или там, где они были в последний раз.", "home.h": "Что умеет", "home.l1": "Запоминает, где вы были, когда устройство подключилось или отключилось, и показывает это на карте.", "home.l2": "Хранит маршрут за последние 24 часа, чтобы вы могли пройти по своим следам.", "home.l3": "Ведёт к ближайшему устройству по уровню сигнала, тактильному отклику и, по желанию, подсказкам направления через AR или AirPods.", "home.l4": "<b>Всё остаётся на вашем iPhone.</b> Без аккаунта, без отправки данных, без аналитики.", "priv.title": "Политика конфиденциальности", "priv.h1": "Кратко", "priv.p1": "Blueee не собирает, не отправляет, не продаёт и не передаёт персональные данные. В приложении нет аккаунтов, серверов, аналитических и рекламных SDK. Все данные хранятся на вашем iPhone.", "priv.h2": "Какие данные приложение использует на вашем устройстве", "priv.loc": "<b>Геолокация</b> (в том числе «Всегда», если вы разрешите): запоминает, где вы были при подключении или отключении устройства, и хранит маршрут за 24 часа. Хранится локально; старые точки удаляются автоматически.", "priv.ble": "<b>Bluetooth</b>: подключается к добавленным вами устройствам, в фоне замечает подключение и отключение и считывает уровень сигнала. Имена и идентификаторы хранятся локально.", "priv.cam": "<b>Камера</b> («Пройдите, чтобы найти»): ARKit отслеживает маршрут телефона. Изображения обрабатываются на лету и никогда не фотографируются, не сохраняются и не отправляются.", "priv.mot": "<b>Движение</b> (отслеживание головы в AirPods): считывается на лету для направления звука; не сохраняется и не отправляется.", "priv.h3": "Передача и хранение", "priv.p3": "Эти данные не покидают ваше устройство, поэтому у нас нет к ним доступа, и мы не можем ими делиться или продавать их. При удалении приложения данные удаляются. Любое разрешение можно отозвать в Настройки iOS → Blueee.", "priv.h4": "Дети", "priv.p4": "Blueee сознательно не собирает данные ни о ком, включая детей.", "priv.h5": "Изменения и контакты", "priv.p5": "Если политика изменится, дата ниже будет обновлена. Вопросы: создайте issue на <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Условия использования", "terms.h1": "Использование приложения", "terms.p1": "Blueee предоставляется бесплатно для личного использования. Используя его, вы принимаете эти условия. Также действует стандартное лицензионное соглашение Apple для лицензируемых приложений.", "terms.h2": "Нет гарантии, что устройство найдётся", "terms.p2": "Местоположение, уровень сигнала Bluetooth и подсказки направления — лишь оценки. Они могут быть неверны или недоступны (например, если устройство выключено, вне зоны или iOS ограничивает работу в фоне). Не полагайтесь на Blueee для критически важного или дорогостоящего отслеживания.", "terms.h3": "Допустимое использование", "terms.p3": "Используйте Blueee только с устройствами, которые принадлежат вам или которые вам разрешено искать, никогда — для слежки за людьми, и соблюдайте местное законодательство.", "terms.h4": "Гарантии и ответственность", "terms.p4": "Приложение предоставляется «как есть», без гарантий. В пределах, допустимых законом, разработчик не отвечает за утрату или повреждение устройств и данных при использовании приложения.", "terms.h5": "Изменения", "terms.p5": "Условия могут обновляться; продолжая пользоваться приложением, вы принимаете их.", "sup.title": "Поддержка", "sup.h1": "Получить помощь", "sup.p1": "Создайте issue на <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>, указав модель iPhone, версию iOS и что произошло.", "sup.h2": "Частые вопросы", "sup.q1": "Зачем нужна геолокация «Всегда»?", "sup.a1": "Чтобы запомнить, где вы были в момент отключения устройства, когда приложение в фоне. Вариант «При использовании» тоже работает, но может пропускать отключения в фоне.", "sup.q2": "Отправляются ли мои данные?", "sup.a2": "Нет. Всё остаётся на вашем iPhone. См. <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Устройство не определяется в фоне.", "sup.a3": "Убедитесь, что Bluetooth включён, обновление контента разрешено, а приложение не было принудительно закрыто в переключателе приложений.", "foot": "© 2026 Blueee · Обновлено: 2026-11-09", "privacyLink": "Политика конфиденциальности"}, "ar": {"name": "العربية", "nav.home": "الرئيسية", "nav.privacy": "الخصوصية", "nav.terms": "الشروط", "nav.support": "الدعم", "home.tag": "اعثر على أجهزة البلوتوث الخاصة بك: القريبة منك، أو حيث كانت آخر مرة.", "home.h": "ماذا يفعل", "home.l1": "يتذكّر أين كنت عندما يتصل جهاز أو ينقطع اتصاله، ويعرض ذلك على الخريطة.", "home.l2": "يحتفظ بمسارك لآخر 24 ساعة لتتمكن من تتبّع خطواتك.", "home.l3": "يرشدك إلى جهاز قريب بقوة الإشارة والاهتزاز، ويمكنك اختياريًا استخدام إرشادات الاتجاه عبر الواقع المعزز أو AirPods.", "home.l4": "<b>كل شيء يبقى على iPhone الخاص بك.</b> بلا حساب، ولا رفع بيانات، ولا تحليلات.", "priv.title": "سياسة الخصوصية", "priv.h1": "الملخص", "priv.p1": "لا يجمع Blueee أي بيانات شخصية ولا يرفعها ولا يبيعها ولا يشاركها. لا توجد حسابات ولا خوادم ولا حزم تحليلات أو إعلانات. جميع البيانات موجودة على iPhone الخاص بك.", "priv.h2": "البيانات التي يستخدمها التطبيق على جهازك", "priv.loc": "<b>الموقع</b> (بما في ذلك «دائمًا» إذا سمحت به): يسجّل أين كنت عند اتصال جهاز أو انقطاعه ويحتفظ بمسار 24 ساعة. يُخزَّن محليًا وتُحذف النقاط القديمة تلقائيًا.", "priv.ble": "<b>البلوتوث</b>: يتصل بالأجهزة التي تضيفها، ويكتشف الاتصال والانقطاع في الخلفية، ويقرأ قوة الإشارة. تُخزَّن الأسماء والمعرّفات محليًا.", "priv.cam": "<b>الكاميرا</b> («امشِ للتحديد»): يتتبّع ARKit المسار الذي يسلكه هاتفك. تُعالَج الصور لحظيًا ولا تُلتقط ولا تُحفظ ولا تُرفع أبدًا.", "priv.mot": "<b>الحركة</b> (تتبّع الرأس في AirPods): تُقرأ لحظيًا لتوجيه الصوت، ولا تُحفظ ولا تُرفع أبدًا.", "priv.h3": "المشاركة والاحتفاظ", "priv.p3": "لا تغادر أي من هذه البيانات جهازك، لذلك لا يمكننا الوصول إليها أو مشاركتها أو بيعها. يؤدي حذف التطبيق إلى حذف بياناته. يمكنك إلغاء أي إذن من إعدادات iOS ← Blueee.", "priv.h4": "الأطفال", "priv.p4": "لا يجمع Blueee عن علم أي بيانات من أي شخص، بمن فيهم الأطفال.", "priv.h5": "التغييرات والتواصل", "priv.p5": "إذا تغيّرت هذه السياسة فسيُحدَّث التاريخ أدناه. للاستفسار: افتح issue على <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "شروط الاستخدام", "terms.h1": "استخدام التطبيق", "terms.p1": "يُقدَّم Blueee مجانًا للاستخدام الشخصي. باستخدامه فإنك توافق على هذه الشروط. وتنطبق أيضًا اتفاقية ترخيص المستخدم النهائي القياسية من Apple للتطبيقات المرخّصة.", "terms.h2": "لا ضمان للعثور على الجهاز", "terms.p2": "الموقع وقوة إشارة البلوتوث وإرشادات الاتجاه مجرد تقديرات. قد تكون غير دقيقة أو غير متاحة (مثلًا عندما يكون الجهاز مغلقًا أو خارج النطاق أو يقيّد iOS النشاط في الخلفية). لا تعتمد على Blueee في التتبّع الحرج أو عالي القيمة.", "terms.h3": "الاستخدام المقبول", "terms.p3": "استخدم Blueee فقط مع الأجهزة التي تملكها أو لديك إذن بتحديد موقعها، ولا تستخدمه أبدًا لتتبّع الأشخاص، والتزم بالقوانين المحلية.", "terms.h4": "الضمان والمسؤولية", "terms.p4": "يُقدَّم التطبيق «كما هو» دون أي ضمانات. وبالقدر الذي يسمح به القانون، لا يتحمّل المطوّر مسؤولية فقدان أو تلف أي جهاز أو بيانات ناتج عن استخدام التطبيق.", "terms.h5": "التغييرات", "terms.p5": "قد تُحدَّث هذه الشروط؛ ويعني استمرارك في الاستخدام قبولها.", "sup.title": "الدعم", "sup.h1": "احصل على مساعدة", "sup.p1": "افتح issue على <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> مع ذكر طراز iPhone وإصدار iOS وما حدث.", "sup.h2": "الأسئلة الشائعة", "sup.q1": "لماذا يطلب إذن الموقع «دائمًا»؟", "sup.a1": "ليتمكن من تسجيل مكانك لحظة انقطاع اتصال جهاز بينما التطبيق في الخلفية. يعمل خيار «أثناء الاستخدام» أيضًا لكنه قد يفوّت حالات الانقطاع في الخلفية.", "sup.q2": "هل تُرفع بياناتي؟", "sup.a2": "لا. كل شيء يبقى على iPhone الخاص بك. راجع <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "لا يتم اكتشاف جهاز في الخلفية.", "sup.a3": "تأكد من تشغيل البلوتوث ومن السماح بتحديث التطبيقات في الخلفية ومن عدم إغلاق التطبيق قسرًا من مبدّل التطبيقات.", "foot": "© 2026 Blueee · آخر تحديث: 2026-11-09", "privacyLink": "سياسة الخصوصية"}, "hi": {"name": "हिन्दी", "nav.home": "होम", "nav.privacy": "गोपनीयता", "nav.terms": "शर्तें", "nav.support": "सहायता", "home.tag": "अपने ब्लूटूथ डिवाइस खोजें: पास में हों तो रास्ता दिखाए, खो जाएँ तो आख़िरी जगह बताए।", "home.h": "यह क्या करता है", "home.l1": "जब कोई डिवाइस कनेक्ट या डिसकनेक्ट होता है, तब आप कहाँ थे यह याद रखता है और नक्शे पर दिखाता है।", "home.l2": "24 घंटे का रास्ता सहेजता है ताकि आप अपने कदम दोहरा सकें।", "home.l3": "सिग्नल की ताकत, हैप्टिक और वैकल्पिक AR / AirPods दिशा-संकेतों से पास के डिवाइस तक पहुँचाता है।", "home.l4": "<b>सब कुछ आपके iPhone पर ही रहता है।</b> कोई खाता नहीं, कोई अपलोड नहीं, कोई एनालिटिक्स नहीं।", "priv.title": "गोपनीयता नीति", "priv.h1": "सारांश", "priv.p1": "Blueee कोई व्यक्तिगत डेटा एकत्र, अपलोड, बेचता या साझा नहीं करता। इसमें कोई खाते, सर्वर, या एनालिटिक्स/विज्ञापन SDK नहीं हैं। सारा डेटा आपके iPhone पर रहता है।", "priv.h2": "ऐप आपके डिवाइस पर कौन-सा डेटा उपयोग करता है", "priv.loc": "<b>स्थान</b> (आप अनुमति दें तो “हमेशा” सहित): डिवाइस के कनेक्ट या डिसकनेक्ट होने पर आप कहाँ थे यह दर्ज करता है और 24 घंटे का रास्ता रखता है। स्थानीय रूप से संग्रहीत; पुराने बिंदु अपने-आप हट जाते हैं।", "priv.ble": "<b>ब्लूटूथ</b>: आपके जोड़े गए डिवाइस से कनेक्ट होता है, बैकग्राउंड में कनेक्ट/डिसकनेक्ट पहचानता है और सिग्नल की ताकत पढ़ता है। नाम और पहचानकर्ता स्थानीय रूप से संग्रहीत रहते हैं।", "priv.cam": "<b>कैमरा</b> (“चलकर खोजें”): ARKit आपके फ़ोन के चलने का रास्ता ट्रैक करता है। छवियाँ तुरंत प्रोसेस होती हैं; कभी फ़ोटो, सहेजी या अपलोड नहीं की जातीं।", "priv.mot": "<b>मोशन</b> (AirPods हेड ट्रैकिंग): ध्वनि की दिशा तय करने के लिए तुरंत पढ़ा जाता है; कभी सहेजा या अपलोड नहीं किया जाता।", "priv.h3": "साझा करना और अवधि", "priv.p3": "इनमें से कोई डेटा आपके डिवाइस से बाहर नहीं जाता, इसलिए हम उसे देख, साझा या बेच नहीं सकते। ऐप हटाने पर उसका डेटा भी हट जाता है। आप iOS सेटिंग्स → Blueee में कोई भी अनुमति वापस ले सकते हैं।", "priv.h4": "बच्चे", "priv.p4": "Blueee जानबूझकर किसी से, बच्चों सहित, कोई डेटा एकत्र नहीं करता।", "priv.h5": "बदलाव और संपर्क", "priv.p5": "यह नीति बदलने पर नीचे की तारीख़ अपडेट होगी। प्रश्न: <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> पर issue खोलें।", "terms.title": "उपयोग की शर्तें", "terms.h1": "ऐप का उपयोग", "terms.p1": "Blueee व्यक्तिगत उपयोग के लिए निःशुल्क है। इसका उपयोग करके आप इन शर्तों से सहमत होते हैं। Apple का मानक लाइसेंस्ड एप्लिकेशन एंड यूज़र लाइसेंस एग्रीमेंट भी लागू है।", "terms.h2": "डिवाइस मिलने की कोई गारंटी नहीं", "terms.p2": "स्थान, ब्लूटूथ सिग्नल की ताकत और दिशा-संकेत केवल अनुमान हैं। वे गलत या अनुपलब्ध हो सकते हैं (जैसे डिवाइस बंद हो, दायरे से बाहर हो, या iOS बैकग्राउंड गतिविधि सीमित करे)। गंभीर या अधिक मूल्य वाली ट्रैकिंग के लिए Blueee पर निर्भर न रहें।", "terms.h3": "स्वीकार्य उपयोग", "terms.p3": "Blueee का उपयोग केवल उन डिवाइस के साथ करें जो आपके हैं या जिन्हें खोजने की आपको अनुमति है; लोगों को ट्रैक करने के लिए कभी नहीं, और स्थानीय कानूनों का पालन करें।", "terms.h4": "वारंटी और दायित्व", "terms.p4": "ऐप “जैसा है” आधार पर बिना किसी वारंटी के दिया गया है। कानून द्वारा अनुमत सीमा तक, ऐप के उपयोग से किसी डिवाइस या डेटा के नुकसान के लिए डेवलपर उत्तरदायी नहीं है।", "terms.h5": "बदलाव", "terms.p5": "ये शर्तें अपडेट हो सकती हैं; उपयोग जारी रखने का अर्थ स्वीकृति है।", "sup.title": "सहायता", "sup.h1": "मदद पाएँ", "sup.p1": "<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> पर issue खोलें और अपना iPhone मॉडल, iOS संस्करण और समस्या बताएँ।", "sup.h2": "अक्सर पूछे जाने वाले प्रश्न", "sup.q1": "यह “हमेशा” स्थान क्यों माँगता है?", "sup.a1": "ताकि ऐप बैकग्राउंड में हो तब भी डिवाइस डिसकनेक्ट होने के क्षण आपकी जगह दर्ज हो सके। “ऐप उपयोग के दौरान” भी काम करता है, पर बैकग्राउंड में हुए डिसकनेक्ट छूट सकते हैं।", "sup.q2": "क्या मेरा डेटा अपलोड होता है?", "sup.a2": "नहीं। सब कुछ आपके iPhone पर रहता है। देखें <a href=\"privacy.html\">Privacy Policy</a>।", "sup.q3": "बैकग्राउंड में डिवाइस पहचाना नहीं जा रहा।", "sup.a3": "जाँचें कि ब्लूटूथ चालू है, बैकग्राउंड ऐप रिफ़्रेश की अनुमति है, और ऐप को ऐप स्विचर से ज़बरदस्ती बंद नहीं किया गया है।", "foot": "© 2026 Blueee · अंतिम अपडेट: 2026-11-09", "privacyLink": "गोपनीयता नीति"}, "bn": {"name": "বাংলা", "nav.home": "হোম", "nav.privacy": "গোপনীয়তা", "nav.terms": "শর্তাবলী", "nav.support": "সহায়তা", "home.tag": "আপনার ব্লুটুথ ডিভাইস খুঁজুন: কাছে থাকলে পথ দেখাবে, হারালে শেষ কোথায় ছিল জানাবে।", "home.h": "এটি কী করে", "home.l1": "কোনো ডিভাইস সংযুক্ত বা বিচ্ছিন্ন হলে আপনি কোথায় ছিলেন তা মনে রাখে এবং মানচিত্রে দেখায়।", "home.l2": "২৪ ঘণ্টার পথ সংরক্ষণ করে, যাতে আপনি আপনার পথ ধরে ফিরে যেতে পারেন।", "home.l3": "সিগন্যালের শক্তি, হ্যাপটিক এবং ঐচ্ছিক AR / AirPods দিকনির্দেশ দিয়ে কাছের ডিভাইস পর্যন্ত নিয়ে যায়।", "home.l4": "<b>সবকিছু আপনার iPhone-এই থাকে।</b> কোনো অ্যাকাউন্ট নেই, আপলোড নেই, অ্যানালিটিক্স নেই।", "priv.title": "গোপনীয়তা নীতি", "priv.h1": "সারসংক্ষেপ", "priv.p1": "Blueee কোনো ব্যক্তিগত তথ্য সংগ্রহ, আপলোড, বিক্রি বা শেয়ার করে না। এতে অ্যাকাউন্ট, সার্ভার বা অ্যানালিটিক্স/বিজ্ঞাপন SDK নেই। সব তথ্য আপনার iPhone-এ থাকে।", "priv.h2": "অ্যাপ আপনার ডিভাইসে যে তথ্য ব্যবহার করে", "priv.loc": "<b>অবস্থান</b> (আপনি অনুমতি দিলে “সবসময়” সহ): ডিভাইস সংযুক্ত বা বিচ্ছিন্ন হলে আপনি কোথায় ছিলেন তা রেকর্ড করে এবং ২৪ ঘণ্টার পথ রাখে। স্থানীয়ভাবে সংরক্ষিত; পুরোনো পয়েন্ট নিজে থেকেই মুছে যায়।", "priv.ble": "<b>ব্লুটুথ</b>: আপনার যোগ করা ডিভাইসের সঙ্গে সংযুক্ত হয়, ব্যাকগ্রাউন্ডে সংযোগ/বিচ্ছিন্ন হওয়া শনাক্ত করে এবং সিগন্যালের শক্তি পড়ে। নাম ও শনাক্তকারী স্থানীয়ভাবে সংরক্ষিত থাকে।", "priv.cam": "<b>ক্যামেরা</b> (“হেঁটে খুঁজুন”): ARKit আপনার ফোনের হাঁটার পথ ট্র্যাক করে। ছবি সঙ্গে সঙ্গে প্রসেস হয়; কখনো তোলা, সংরক্ষণ বা আপলোড করা হয় না।", "priv.mot": "<b>মোশন</b> (AirPods হেড ট্র্যাকিং): শব্দের দিক ঠিক করতে সঙ্গে সঙ্গে পড়া হয়; কখনো সংরক্ষণ বা আপলোড করা হয় না।", "priv.h3": "শেয়ার ও সংরক্ষণ", "priv.p3": "এই তথ্যের কিছুই আপনার ডিভাইস ছেড়ে যায় না, তাই আমরা তা দেখতে, শেয়ার করতে বা বিক্রি করতে পারি না। অ্যাপ মুছলে এর তথ্যও মুছে যায়। iOS সেটিংস → Blueee থেকে যেকোনো অনুমতি প্রত্যাহার করতে পারেন।", "priv.h4": "শিশু", "priv.p4": "Blueee জেনেশুনে কারও কাছ থেকে, শিশুদের সহ, কোনো তথ্য সংগ্রহ করে না।", "priv.h5": "পরিবর্তন ও যোগাযোগ", "priv.p5": "এই নীতি বদলালে নিচের তারিখ হালনাগাদ হবে। প্রশ্ন থাকলে <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>-এ issue খুলুন।", "terms.title": "ব্যবহারের শর্তাবলী", "terms.h1": "অ্যাপের ব্যবহার", "terms.p1": "Blueee ব্যক্তিগত ব্যবহারের জন্য বিনামূল্যে দেওয়া হয়। ব্যবহার করলে আপনি এই শর্তে সম্মত হচ্ছেন। Apple-এর মানক লাইসেন্সপ্রাপ্ত অ্যাপ্লিকেশন এন্ড ইউজার লাইসেন্স চুক্তিও প্রযোজ্য।", "terms.h2": "ডিভাইস খুঁজে পাওয়ার নিশ্চয়তা নেই", "terms.p2": "অবস্থান, ব্লুটুথ সিগন্যালের শক্তি ও দিকনির্দেশ কেবল আনুমানিক। এগুলো ভুল বা অনুপলব্ধ হতে পারে (যেমন ডিভাইস বন্ধ, নাগালের বাইরে, বা iOS ব্যাকগ্রাউন্ড কার্যকলাপ সীমিত করলে)। গুরুত্বপূর্ণ বা উচ্চমূল্যের ট্র্যাকিংয়ের জন্য Blueee-র উপর নির্ভর করবেন না।", "terms.h3": "গ্রহণযোগ্য ব্যবহার", "terms.p3": "Blueee শুধু আপনার নিজের বা খুঁজে বের করার অনুমতি আছে এমন ডিভাইসের সঙ্গে ব্যবহার করুন; কখনো মানুষকে ট্র্যাক করতে নয়, এবং স্থানীয় আইন মেনে চলুন।", "terms.h4": "ওয়ারেন্টি ও দায়", "terms.p4": "অ্যাপটি “যেমন আছে” ভিত্তিতে কোনো ওয়ারেন্টি ছাড়া দেওয়া হয়। আইনে অনুমোদিত সীমা পর্যন্ত, অ্যাপ ব্যবহারের ফলে কোনো ডিভাইস বা তথ্যের ক্ষতির জন্য ডেভেলপার দায়ী নন।", "terms.h5": "পরিবর্তন", "terms.p5": "এই শর্তাবলী হালনাগাদ হতে পারে; ব্যবহার চালিয়ে গেলে তা গ্রহণ করা হয়েছে ধরা হবে।", "sup.title": "সহায়তা", "sup.h1": "সাহায্য নিন", "sup.p1": "<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>-এ issue খুলে আপনার iPhone মডেল, iOS সংস্করণ এবং কী ঘটেছে জানান।", "sup.h2": "প্রায়ই জিজ্ঞাসিত প্রশ্ন", "sup.q1": "কেন “সবসময়” অবস্থান চায়?", "sup.a1": "যাতে অ্যাপ ব্যাকগ্রাউন্ডে থাকলেও ডিভাইস বিচ্ছিন্ন হওয়ার মুহূর্তে আপনার অবস্থান রেকর্ড করা যায়। “ব্যবহারের সময়” দিলেও কাজ করে, তবে ব্যাকগ্রাউন্ডের বিচ্ছিন্নতা বাদ পড়তে পারে।", "sup.q2": "আমার তথ্য কি আপলোড হয়?", "sup.a2": "না। সবকিছু আপনার iPhone-এই থাকে। দেখুন <a href=\"privacy.html\">Privacy Policy</a>।", "sup.q3": "ব্যাকগ্রাউন্ডে ডিভাইস শনাক্ত হচ্ছে না।", "sup.a3": "ব্লুটুথ চালু আছে, ব্যাকগ্রাউন্ড অ্যাপ রিফ্রেশ অনুমোদিত, এবং অ্যাপ সুইচার থেকে অ্যাপটি জোর করে বন্ধ করা হয়নি তা নিশ্চিত করুন।", "foot": "© 2026 Blueee · সর্বশেষ হালনাগাদ: 2026-11-09", "privacyLink": "গোপনীয়তা নীতি"}, "ur": {"name": "اردو", "nav.home": "ہوم", "nav.privacy": "رازداری", "nav.terms": "شرائط", "nav.support": "معاونت", "home.tag": "اپنے بلوٹوتھ آلات تلاش کریں: قریب ہوں تو راستہ دکھائے، کھو جائیں تو آخری جگہ بتائے۔", "home.h": "یہ کیا کرتی ہے", "home.l1": "جب کوئی آلہ جڑتا یا منقطع ہوتا ہے تو یاد رکھتی ہے کہ آپ کہاں تھے اور اسے نقشے پر دکھاتی ہے۔", "home.l2": "24 گھنٹے کا راستہ محفوظ رکھتی ہے تاکہ آپ اپنے قدموں کے نشان پر واپس جا سکیں۔", "home.l3": "سگنل کی طاقت، ہیپٹک اور اختیاری AR / AirPods سمتی اشاروں سے قریبی آلے تک پہنچاتی ہے۔", "home.l4": "<b>سب کچھ آپ کے iPhone پر ہی رہتا ہے۔</b> کوئی اکاؤنٹ نہیں، کوئی اپ لوڈ نہیں، کوئی اینالیٹکس نہیں۔", "priv.title": "رازداری کی پالیسی", "priv.h1": "خلاصہ", "priv.p1": "Blueee کوئی ذاتی ڈیٹا جمع، اپ لوڈ، فروخت یا شیئر نہیں کرتی۔ اس میں کوئی اکاؤنٹ، سرور یا اینالیٹکس/اشتہاری SDK نہیں ہے۔ تمام ڈیٹا آپ کے iPhone پر رہتا ہے۔", "priv.h2": "ایپ آپ کے آلے پر کون سا ڈیٹا استعمال کرتی ہے", "priv.loc": "<b>مقام</b> (اگر آپ اجازت دیں تو “ہمیشہ” سمیت): آلہ جڑنے یا منقطع ہونے پر ریکارڈ کرتی ہے کہ آپ کہاں تھے اور 24 گھنٹے کا راستہ رکھتی ہے۔ مقامی طور پر محفوظ؛ پرانے نقاط خود بخود ہٹ جاتے ہیں۔", "priv.ble": "<b>بلوٹوتھ</b>: آپ کے شامل کردہ آلات سے جڑتی ہے، پس منظر میں جڑنے/منقطع ہونے کا پتا لگاتی ہے اور سگنل کی طاقت پڑھتی ہے۔ نام اور شناخت کنندہ مقامی طور پر محفوظ رہتے ہیں۔", "priv.cam": "<b>کیمرا</b> (“چل کر تلاش کریں”): ARKit آپ کے فون کا چلنے کا راستہ ٹریک کرتا ہے۔ تصاویر فوراً پروسیس ہوتی ہیں؛ کبھی کھینچی، محفوظ یا اپ لوڈ نہیں کی جاتیں۔", "priv.mot": "<b>حرکت</b> (AirPods ہیڈ ٹریکنگ): آواز کی سمت درست کرنے کے لیے فوراً پڑھی جاتی ہے؛ کبھی محفوظ یا اپ لوڈ نہیں کی جاتی۔", "priv.h3": "شیئرنگ اور برقراری", "priv.p3": "ان میں سے کوئی ڈیٹا آپ کے آلے سے باہر نہیں جاتا، اس لیے ہم اسے دیکھ، شیئر یا فروخت نہیں کر سکتے۔ ایپ حذف کرنے سے اس کا ڈیٹا بھی حذف ہو جاتا ہے۔ آپ iOS سیٹنگز ← Blueee میں کوئی بھی اجازت واپس لے سکتے ہیں۔", "priv.h4": "بچے", "priv.p4": "Blueee جان بوجھ کر کسی سے، بچوں سمیت، کوئی ڈیٹا جمع نہیں کرتی۔", "priv.h5": "تبدیلیاں اور رابطہ", "priv.p5": "اگر یہ پالیسی بدلی تو نیچے کی تاریخ اپڈیٹ ہو گی۔ سوالات کے لیے <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> پر issue کھولیں۔", "terms.title": "استعمال کی شرائط", "terms.h1": "ایپ کا استعمال", "terms.p1": "Blueee ذاتی استعمال کے لیے مفت فراہم کی جاتی ہے۔ اسے استعمال کر کے آپ ان شرائط سے اتفاق کرتے ہیں۔ Apple کا معیاری لائسنس یافتہ ایپلیکیشن اینڈ یوزر لائسنس معاہدہ بھی لاگو ہے۔", "terms.h2": "آلہ مل جانے کی کوئی ضمانت نہیں", "terms.p2": "مقام، بلوٹوتھ سگنل کی طاقت اور سمتی اشارے صرف اندازے ہیں۔ یہ غلط یا دستیاب نہ ہو سکتے ہیں (مثلاً آلہ بند ہو، دائرے سے باہر ہو، یا iOS پس منظر کی سرگرمی محدود کرے)۔ اہم یا قیمتی ٹریکنگ کے لیے Blueee پر انحصار نہ کریں۔", "terms.h3": "قابلِ قبول استعمال", "terms.p3": "Blueee صرف ایسے آلات کے ساتھ استعمال کریں جو آپ کے ہوں یا جنہیں تلاش کرنے کی آپ کو اجازت ہو؛ لوگوں کو ٹریک کرنے کے لیے ہرگز نہیں، اور مقامی قوانین کی پابندی کریں۔", "terms.h4": "وارنٹی اور ذمہ داری", "terms.p4": "ایپ “جیسی ہے” کی بنیاد پر بغیر کسی وارنٹی کے فراہم کی جاتی ہے۔ قانون کی اجازت کی حد تک، ایپ کے استعمال سے کسی آلے یا ڈیٹا کے نقصان کا ڈیولپر ذمہ دار نہیں۔", "terms.h5": "تبدیلیاں", "terms.p5": "یہ شرائط اپڈیٹ ہو سکتی ہیں؛ استعمال جاری رکھنے کا مطلب قبولیت ہے۔", "sup.title": "معاونت", "sup.h1": "مدد حاصل کریں", "sup.p1": "<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> پر issue کھولیں اور اپنا iPhone ماڈل، iOS ورژن اور مسئلہ بتائیں۔", "sup.h2": "اکثر پوچھے جانے والے سوالات", "sup.q1": "یہ “ہمیشہ” مقام کیوں مانگتی ہے؟", "sup.a1": "تاکہ ایپ پس منظر میں ہو تب بھی آلہ منقطع ہونے کے لمحے آپ کا مقام ریکارڈ ہو سکے۔ “استعمال کے دوران” بھی کام کرتا ہے، مگر پس منظر کے انقطاع چھوٹ سکتے ہیں۔", "sup.q2": "کیا میرا ڈیٹا اپ لوڈ ہوتا ہے؟", "sup.a2": "نہیں۔ سب کچھ آپ کے iPhone پر رہتا ہے۔ دیکھیں <a href=\"privacy.html\">Privacy Policy</a>۔", "sup.q3": "پس منظر میں آلہ شناخت نہیں ہو رہا۔", "sup.a3": "یقینی بنائیں کہ بلوٹوتھ آن ہے، بیک گراؤنڈ ایپ ریفریش کی اجازت ہے، اور ایپ کو ایپ سوئچر سے زبردستی بند نہیں کیا گیا۔", "foot": "© 2026 Blueee · آخری اپڈیٹ: 2026-11-09", "privacyLink": "رازداری کی پالیسی"}, "zh-Hant": {"name": "繁體中文", "nav.home": "首頁", "nav.privacy": "隱私", "nav.terms": "條款", "nav.support": "支援", "home.tag": "找到你的藍牙裝置：在身邊就帶你走過去，遺失了就告訴你最後在哪。", "home.h": "功能", "home.l1": "裝置連線或中斷時記錄你所在的位置，並顯示在地圖上。", "home.l2": "保留 24 小時軌跡，方便回頭尋找。", "home.l3": "透過訊號強度、觸感，以及可選的 AR / AirPods 方向提示，帶你走到身邊的裝置。", "home.l4": "<b>所有資料只儲存在你的 iPhone 上。</b>無需帳號、不上傳、無統計分析。", "priv.title": "隱私權政策", "priv.h1": "概述", "priv.p1": "Blueee 不會蒐集、上傳、販售或分享任何個人資料。沒有帳號、沒有伺服器，也沒有分析或廣告 SDK。所有資料只儲存在你的 iPhone 上。", "priv.h2": "App 在你裝置上使用的資料", "priv.loc": "<b>位置</b>（若你允許「永遠」）：記錄裝置連線或中斷時你所在的位置，並保留 24 小時軌跡。僅儲存在本機，過期自動清除。", "priv.ble": "<b>藍牙</b>：連接你新增的裝置、在背景偵測連線與中斷、讀取訊號強度。裝置名稱與識別碼僅儲存在本機。", "priv.cam": "<b>相機</b>（「走一走定位」）：ARKit 追蹤手機走過的路線。影像即時處理，不會拍照、儲存或上傳。", "priv.mot": "<b>動作</b>（AirPods 頭部追蹤）：即時讀取以調整聲音方向，不會儲存或上傳。", "priv.h3": "分享與保留", "priv.p3": "這些資料不會離開你的裝置，因此我們無法存取、分享或販售。刪除 App 即刪除其全部資料；你可隨時在 iOS 設定 → Blueee 中撤銷權限。", "priv.h4": "兒童", "priv.p4": "Blueee 不會刻意蒐集任何人（包括兒童）的資料。", "priv.h5": "變更與聯絡", "priv.p5": "本政策變更時，下方日期會更新。如有問題，請至 <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> 提出 issue。", "terms.title": "使用條款", "terms.h1": "使用說明", "terms.p1": "Blueee 免費提供，僅供個人使用。使用即表示你同意這些條款，同時適用 Apple 標準的授權應用程式使用者授權合約。", "terms.h2": "不保證一定能找到裝置", "terms.p2": "位置、藍牙訊號強度與方向提示都只是估計，裝置關機、超出範圍或 iOS 限制背景活動時可能不準確或無法使用。請勿用於安全攸關或高價值的追蹤。", "terms.h3": "合理使用", "terms.p3": "僅用於你自己的或已獲授權的裝置，不得用於追蹤他人，並請遵守當地法律。", "terms.h4": "保固與責任", "terms.p4": "本 App 依「現狀」提供，不附任何保固。在法律允許的範圍內，開發者對因使用本 App 造成的裝置或資料損失不負責任。", "terms.h5": "變更", "terms.p5": "條款可能更新，繼續使用即視為接受。", "sup.title": "支援", "sup.h1": "取得協助", "sup.p1": "請至 <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> 提出 issue，並附上 iPhone 型號、iOS 版本與遇到的問題。", "sup.h2": "常見問題", "sup.q1": "為什麼要求「永遠」位置？", "sup.a1": "這樣 App 在背景時，裝置中斷連線的瞬間也能記下你的位置。選「使用期間」也能使用，但可能漏掉背景中斷。", "sup.q2": "資料會上傳嗎？", "sup.a2": "不會，全部儲存在你的 iPhone 上。詳見<a href=\"privacy.html\">Privacy Policy</a>。", "sup.q3": "背景偵測不到裝置。", "sup.a3": "請確認藍牙已開啟、已允許「背景 App 重新整理」，且沒有在 App 切換器中強制關閉 App。", "foot": "© 2026 Blueee · 最後更新 2026-11-09", "privacyLink": "隱私權政策"}, "ja": {"name": "日本語", "nav.home": "ホーム", "nav.privacy": "プライバシー", "nav.terms": "利用規約", "nav.support": "サポート", "home.tag": "Bluetooth デバイスを見つけよう。近くにあれば案内し、なくしたら最後の場所を教えます。", "home.h": "できること", "home.l1": "デバイスが接続・切断された時にいた場所を記録し、地図に表示します。", "home.l2": "24 時間分の軌跡を残すので、来た道をたどれます。", "home.l3": "電波の強さ、触覚、そして任意の AR / AirPods の方向ガイドで、近くのデバイスまで案内します。", "home.l4": "<b>すべてのデータは iPhone の中だけに保存されます。</b>アカウント不要、アップロードなし、解析なし。", "priv.title": "プライバシーポリシー", "priv.h1": "概要", "priv.p1": "Blueee は個人データを収集・アップロード・販売・共有しません。アカウントもサーバーも、解析や広告の SDK もありません。すべてのデータは iPhone に保存されます。", "priv.h2": "アプリがデバイス上で使用するデータ", "priv.loc": "<b>位置情報</b>（「常に」を許可した場合を含む）：デバイスが接続・切断された時にいた場所を記録し、24 時間分の軌跡を保持します。端末内にのみ保存され、古いデータは自動的に削除されます。", "priv.ble": "<b>Bluetooth</b>：追加したデバイスに接続し、バックグラウンドで接続・切断を検知し、電波の強さを読み取ります。名前と識別子は端末内にのみ保存されます。", "priv.cam": "<b>カメラ</b>（「歩いて探す」）：ARKit が iPhone の歩いた経路を追跡します。映像はその場で処理され、撮影・保存・アップロードされることはありません。", "priv.mot": "<b>モーション</b>（AirPods のヘッドトラッキング）：音の方向を調整するためにリアルタイムで読み取り、保存・アップロードはしません。", "priv.h3": "共有と保持", "priv.p3": "これらのデータは端末の外に出ないため、私たちがアクセス・共有・販売することはできません。アプリを削除するとデータも削除されます。許可は「設定」→ Blueee でいつでも取り消せます。", "priv.h4": "お子様", "priv.p4": "Blueee は、お子様を含め、誰からも故意にデータを収集しません。", "priv.h5": "変更とお問い合わせ", "priv.p5": "本ポリシーを変更した場合は、下の日付を更新します。ご質問は <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> に issue を作成してください。", "terms.title": "利用規約", "terms.h1": "アプリの利用", "terms.p1": "Blueee は個人利用に限り無料で提供されます。利用することで本規約に同意したものとみなされます。Apple の標準使用許諾契約（Licensed Application End User License Agreement）も適用されます。", "terms.h2": "デバイスが見つかる保証はありません", "terms.p2": "位置情報、Bluetooth の電波の強さ、方向ガイドはあくまで推定です。デバイスの電源が切れている、範囲外にある、iOS がバックグラウンド動作を制限している場合などは、不正確または利用できないことがあります。安全に関わる用途や高価な物の追跡には Blueee に頼らないでください。", "terms.h3": "適切な利用", "terms.p3": "Blueee は、ご自身が所有する、または探す許可を得たデバイスにのみ使用してください。人の追跡には決して使用せず、現地の法令を守ってください。", "terms.h4": "保証と責任", "terms.p4": "本アプリは「現状のまま」提供され、いかなる保証もありません。法律で認められる範囲で、開発者は本アプリの使用に起因するデバイスやデータの損失・損害について責任を負いません。", "terms.h5": "変更", "terms.p5": "本規約は更新されることがあります。引き続き利用された場合は同意したものとみなします。", "sup.title": "サポート", "sup.h1": "ヘルプ", "sup.p1": "<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> に issue を作成し、iPhone のモデル、iOS のバージョン、発生した内容をお知らせください。", "sup.h2": "よくある質問", "sup.q1": "なぜ位置情報の「常に」を求めるのですか？", "sup.a1": "アプリがバックグラウンドにあっても、デバイスが切断された瞬間の場所を記録するためです。「使用中のみ」でも動作しますが、バックグラウンドでの切断を記録できないことがあります。", "sup.q2": "データはアップロードされますか？", "sup.a2": "いいえ。すべて iPhone の中に保存されます。<a href=\"privacy.html\">Privacy Policy</a>をご覧ください。", "sup.q3": "バックグラウンドでデバイスが検出されません。", "sup.a3": "Bluetooth がオンで、「Appのバックグラウンド更新」が許可されていること、アプリスイッチャーでアプリを強制終了していないことを確認してください。", "foot": "© 2026 Blueee · 最終更新：2026-11-09", "privacyLink": "プライバシーポリシー"}, "ko": {"name": "한국어", "nav.home": "홈", "nav.privacy": "개인정보", "nav.terms": "약관", "nav.support": "지원", "home.tag": "블루투스 기기를 찾으세요. 가까이 있으면 안내하고, 잃어버리면 마지막 위치를 알려 줍니다.", "home.h": "주요 기능", "home.l1": "기기가 연결되거나 연결이 끊어질 때 있었던 위치를 기억해 지도에 표시합니다.", "home.l2": "24시간 동안의 이동 경로를 저장해 왔던 길을 되짚어 볼 수 있습니다.", "home.l3": "신호 세기, 햅틱, 선택형 AR / AirPods 방향 안내로 가까운 기기까지 안내합니다.", "home.l4": "<b>모든 데이터는 iPhone에만 저장됩니다.</b> 계정도, 업로드도, 분석도 없습니다.", "priv.title": "개인정보 처리방침", "priv.h1": "요약", "priv.p1": "Blueee는 개인 정보를 수집, 업로드, 판매 또는 공유하지 않습니다. 계정과 서버가 없고 분석·광고 SDK도 없습니다. 모든 데이터는 iPhone에 저장됩니다.", "priv.h2": "앱이 기기에서 사용하는 데이터", "priv.loc": "<b>위치</b>(“항상”을 허용한 경우 포함): 기기가 연결되거나 끊어질 때 있었던 위치를 기록하고 24시간 동안의 경로를 보관합니다. 기기 내에만 저장되며 오래된 지점은 자동으로 삭제됩니다.", "priv.ble": "<b>블루투스</b>: 추가한 기기에 연결하고, 백그라운드에서 연결/해제를 감지하며, 신호 세기를 읽습니다. 이름과 식별자는 기기 내에만 저장됩니다.", "priv.cam": "<b>카메라</b>(“걸어서 찾기”): ARKit이 iPhone이 이동한 경로를 추적합니다. 영상은 실시간으로 처리되며 촬영, 저장, 업로드되지 않습니다.", "priv.mot": "<b>모션</b>(AirPods 헤드 트래킹): 소리 방향을 조정하기 위해 실시간으로 읽으며 저장하거나 업로드하지 않습니다.", "priv.h3": "공유 및 보관", "priv.p3": "이 데이터는 기기 밖으로 나가지 않으므로 저희가 접근, 공유, 판매할 수 없습니다. 앱을 삭제하면 데이터도 삭제됩니다. iOS 설정 → Blueee에서 언제든 권한을 해제할 수 있습니다.", "priv.h4": "어린이", "priv.p4": "Blueee는 어린이를 포함해 누구의 데이터도 고의로 수집하지 않습니다.", "priv.h5": "변경 및 문의", "priv.p5": "이 방침이 변경되면 아래 날짜가 업데이트됩니다. 문의는 <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>에 issue를 등록해 주세요.", "terms.title": "이용약관", "terms.h1": "앱 사용", "terms.p1": "Blueee는 개인 용도로 무료 제공됩니다. 사용하면 이 약관에 동의하는 것입니다. Apple의 표준 라이선스 앱 최종 사용자 라이선스 계약도 적용됩니다.", "terms.h2": "기기를 찾는다는 보장은 없습니다", "terms.p2": "위치, 블루투스 신호 세기, 방향 안내는 추정값입니다. 기기가 꺼져 있거나 범위를 벗어났거나 iOS가 백그라운드 활동을 제한하면 부정확하거나 사용할 수 없을 수 있습니다. 안전이 중요한 용도나 고가 물품 추적에 Blueee에 의존하지 마세요.", "terms.h3": "올바른 사용", "terms.p3": "Blueee는 본인 소유이거나 찾을 권한이 있는 기기에만 사용하고, 사람을 추적하는 데 사용하지 마세요. 현지 법률을 준수하세요.", "terms.h4": "보증 및 책임", "terms.p4": "앱은 어떠한 보증 없이 “있는 그대로” 제공됩니다. 법이 허용하는 한도에서 개발자는 앱 사용으로 인한 기기 또는 데이터의 손실이나 손상에 책임지지 않습니다.", "terms.h5": "변경", "terms.p5": "이 약관은 변경될 수 있으며, 계속 사용하면 동의한 것으로 봅니다.", "sup.title": "지원", "sup.h1": "도움 받기", "sup.p1": "<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>에 issue를 등록하고 iPhone 모델, iOS 버전, 발생한 문제를 알려 주세요.", "sup.h2": "자주 묻는 질문", "sup.q1": "왜 “항상” 위치 권한을 요청하나요?", "sup.a1": "앱이 백그라운드에 있을 때도 기기 연결이 끊어지는 순간의 위치를 기록하기 위해서입니다. “앱을 사용하는 동안”도 작동하지만 백그라운드 연결 해제를 놓칠 수 있습니다.", "sup.q2": "내 데이터가 업로드되나요?", "sup.a2": "아니요. 모든 것은 iPhone에만 저장됩니다. <a href=\"privacy.html\">Privacy Policy</a>을 참고하세요.", "sup.q3": "백그라운드에서 기기가 감지되지 않습니다.", "sup.a3": "블루투스가 켜져 있는지, 백그라운드 앱 새로 고침이 허용되어 있는지, 앱 전환기에서 앱을 강제 종료하지 않았는지 확인하세요.", "foot": "© 2026 Blueee · 최종 업데이트: 2026-11-09", "privacyLink": "개인정보 처리방침"}, "de": {"name": "Deutsch", "nav.home": "Start", "nav.privacy": "Datenschutz", "nav.terms": "Nutzungsbedingungen", "nav.support": "Support", "home.tag": "Finde deine Bluetooth-Geräte – in der Nähe oder dort, wo du sie zuletzt hattest.", "home.h": "Was die App kann", "home.l1": "Merkt sich, wo du warst, als ein Gerät verbunden oder getrennt wurde, und zeigt es auf einer Karte.", "home.l2": "Speichert 24 Stunden deiner Route, damit du deinen Weg zurückverfolgen kannst.", "home.l3": "Führt dich mit Signalstärke, Haptik und optionalen AR-/AirPods-Richtungshinweisen zu einem Gerät in der Nähe.", "home.l4": "<b>Alles bleibt auf deinem iPhone.</b> Kein Konto, kein Upload, keine Analyse.", "priv.title": "Datenschutzerklärung", "priv.h1": "Zusammenfassung", "priv.p1": "Blueee erhebt, überträgt, verkauft oder teilt keine personenbezogenen Daten. Es gibt keine Konten, keine Server und keine Analyse- oder Werbe-SDKs. Alle Daten bleiben auf deinem iPhone.", "priv.h2": "Daten, die die App auf deinem Gerät verwendet", "priv.loc": "<b>Standort</b> (auch „Immer“, wenn du es erlaubst): speichert, wo du warst, als ein Gerät verbunden oder getrennt wurde, und behält eine 24-Stunden-Route. Lokal gespeichert; ältere Punkte werden automatisch gelöscht.", "priv.ble": "<b>Bluetooth</b>: verbindet sich mit Geräten, die du hinzufügst, erkennt Verbinden/Trennen im Hintergrund und liest die Signalstärke. Namen und Kennungen werden lokal gespeichert.", "priv.cam": "<b>Kamera</b> („Zum Finden gehen“): ARKit verfolgt die Strecke, die dein iPhone zurücklegt. Bilder werden live verarbeitet und nie aufgenommen, gespeichert oder hochgeladen.", "priv.mot": "<b>Bewegung</b> (AirPods-Kopfverfolgung): wird live gelesen, um den Audiohinweis zu lenken; nie gespeichert oder hochgeladen.", "priv.h3": "Weitergabe und Speicherdauer", "priv.p3": "Keine dieser Daten verlässt dein Gerät, daher können wir sie weder einsehen noch weitergeben oder verkaufen. Beim Löschen der App werden ihre Daten gelöscht. Du kannst jede Berechtigung unter iOS-Einstellungen → Blueee widerrufen.", "priv.h4": "Kinder", "priv.p4": "Blueee erhebt wissentlich keine Daten von irgendjemandem, auch nicht von Kindern.", "priv.h5": "Änderungen und Kontakt", "priv.p5": "Wenn sich diese Erklärung ändert, wird das Datum unten aktualisiert. Fragen: Eröffne ein Issue unter <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Nutzungsbedingungen", "terms.h1": "Nutzung der App", "terms.p1": "Blueee wird kostenlos für den persönlichen Gebrauch bereitgestellt. Mit der Nutzung stimmst du diesen Bedingungen zu. Außerdem gilt Apples Standard-Lizenzvertrag für Endnutzer lizenzierter Apps.", "terms.h2": "Keine Garantie, ein Gerät zu finden", "terms.p2": "Standort, Bluetooth-Signalstärke und Richtungshinweise sind Schätzungen. Sie können falsch oder nicht verfügbar sein (z. B. wenn ein Gerät ausgeschaltet oder außer Reichweite ist oder iOS Hintergrundaktivität einschränkt). Verlasse dich bei sicherheitskritischer oder hochwertiger Ortung nicht auf Blueee.", "terms.h3": "Zulässige Nutzung", "terms.p3": "Nutze Blueee nur mit Geräten, die dir gehören oder die du orten darfst, niemals zur Verfolgung von Personen, und beachte die örtlichen Gesetze.", "terms.h4": "Gewährleistung und Haftung", "terms.p4": "Die App wird „wie besehen“ ohne Gewährleistung bereitgestellt. Soweit gesetzlich zulässig, haftet der Entwickler nicht für Verlust oder Beschädigung von Geräten oder Daten durch die Nutzung der App.", "terms.h5": "Änderungen", "terms.p5": "Diese Bedingungen können aktualisiert werden; die weitere Nutzung gilt als Zustimmung.", "sup.title": "Support", "sup.h1": "Hilfe erhalten", "sup.p1": "Eröffne ein Issue unter <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> mit iPhone-Modell, iOS-Version und einer Beschreibung des Problems.", "sup.h2": "Häufige Fragen", "sup.q1": "Warum wird der Standort „Immer“ angefordert?", "sup.a1": "Damit der Ort erfasst werden kann, an dem du warst, als ein Gerät getrennt wurde, während die App im Hintergrund ist. „Beim Verwenden“ funktioniert auch, kann aber Trennungen im Hintergrund verpassen.", "sup.q2": "Werden meine Daten hochgeladen?", "sup.a2": "Nein. Alles bleibt auf deinem iPhone. Siehe die <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Ein Gerät wird im Hintergrund nicht erkannt.", "sup.a3": "Stelle sicher, dass Bluetooth an ist, die Hintergrundaktualisierung erlaubt ist und die App nicht im App-Umschalter beendet wurde.", "foot": "© 2026 Blueee · Zuletzt aktualisiert: 2026-11-09", "privacyLink": "Datenschutzerklärung"}, "it": {"name": "Italiano", "nav.home": "Home", "nav.privacy": "Privacy", "nav.terms": "Termini", "nav.support": "Supporto", "home.tag": "Trova i tuoi dispositivi Bluetooth: vicini a te, o dove li avevi per ultimi.", "home.h": "Cosa fa", "home.l1": "Ricorda dove ti trovavi quando un dispositivo si connette o si disconnette e lo mostra su una mappa.", "home.l2": "Conserva un percorso di 24 ore per ripercorrere i tuoi passi.", "home.l3": "Ti guida a un dispositivo vicino con intensità del segnale, feedback aptico e, facoltativamente, indicazioni di direzione in AR o con gli AirPods.", "home.l4": "<b>Tutto resta sul tuo iPhone.</b> Nessun account, nessun caricamento, nessuna analisi.", "priv.title": "Informativa sulla privacy", "priv.h1": "Sintesi", "priv.p1": "Blueee non raccoglie, carica, vende né condivide dati personali. Non ci sono account, server né SDK di analisi o pubblicità. Tutti i dati restano sul tuo iPhone.", "priv.h2": "Dati usati dall’app sul tuo dispositivo", "priv.loc": "<b>Posizione</b> (compreso “Sempre”, se lo consenti): registra dove ti trovavi quando un dispositivo si connette o si disconnette e conserva un percorso di 24 ore. Salvata localmente; i punti più vecchi vengono eliminati automaticamente.", "priv.ble": "<b>Bluetooth</b>: si connette ai dispositivi che aggiungi, rileva connessioni e disconnessioni in background e legge l’intensità del segnale. Nomi e identificatori sono salvati localmente.", "priv.cam": "<b>Fotocamera</b> (“Cammina per localizzare”): ARKit segue il percorso del tuo telefono. Le immagini sono elaborate in tempo reale e mai fotografate, salvate o caricate.", "priv.mot": "<b>Movimento</b> (tracciamento della testa degli AirPods): letto in tempo reale per orientare il suono; mai salvato né caricato.", "priv.h3": "Condivisione e conservazione", "priv.p3": "Nessuno di questi dati lascia il tuo dispositivo, quindi non possiamo accedervi, condividerli né venderli. Eliminando l’app ne elimini i dati. Puoi revocare qualsiasi autorizzazione in Impostazioni iOS → Blueee.", "priv.h4": "Minori", "priv.p4": "Blueee non raccoglie consapevolmente dati di nessuno, minori compresi.", "priv.h5": "Modifiche e contatti", "priv.p5": "Se questa informativa cambia, la data qui sotto verrà aggiornata. Domande: apri una issue su <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Termini di utilizzo", "terms.h1": "Uso dell’app", "terms.p1": "Blueee è offerta gratuitamente per uso personale. Utilizzandola accetti questi termini. Si applica anche il contratto di licenza standard di Apple per le app in licenza.", "terms.h2": "Nessuna garanzia di ritrovare un dispositivo", "terms.p2": "Posizione, intensità del segnale Bluetooth e indicazioni di direzione sono stime. Possono essere errate o non disponibili (ad esempio se il dispositivo è spento, fuori portata o iOS limita l’attività in background). Non fare affidamento su Blueee per localizzazioni critiche o di alto valore.", "terms.h3": "Uso consentito", "terms.p3": "Usa Blueee solo con dispositivi tuoi o che hai il permesso di localizzare, mai per rintracciare persone, e rispetta le leggi locali.", "terms.h4": "Garanzia e responsabilità", "terms.p4": "L’app è fornita “così com’è”, senza garanzie. Nei limiti consentiti dalla legge, lo sviluppatore non risponde di perdite o danni a dispositivi o dati derivanti dall’uso dell’app.", "terms.h5": "Modifiche", "terms.p5": "Questi termini possono essere aggiornati; continuare a usare l’app significa accettarli.", "sup.title": "Supporto", "sup.h1": "Ottenere aiuto", "sup.p1": "Apri una issue su <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> indicando il modello di iPhone, la versione di iOS e cosa è successo.", "sup.h2": "Domande frequenti", "sup.q1": "Perché chiede la posizione “Sempre”?", "sup.a1": "Per registrare dove ti trovavi nel momento in cui un dispositivo si disconnette mentre l’app è in background. “Mentre usi l’app” funziona comunque, ma può perdere le disconnessioni in background.", "sup.q2": "I miei dati vengono caricati?", "sup.a2": "No. Tutto resta sul tuo iPhone. Consulta l’<a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Un dispositivo non viene rilevato in background.", "sup.a3": "Verifica che il Bluetooth sia attivo, che l’aggiornamento app in background sia consentito e che l’app non sia stata chiusa forzatamente dal selettore app.", "foot": "© 2026 Blueee · Ultimo aggiornamento: 2026-11-09", "privacyLink": "Informativa sulla privacy"}, "tr": {"name": "Türkçe", "nav.home": "Ana sayfa", "nav.privacy": "Gizlilik", "nav.terms": "Koşullar", "nav.support": "Destek", "home.tag": "Bluetooth cihazlarınızı bulun: yakınınızdaysa yönlendirir, kaybolduysa en son nerede olduğunu söyler.", "home.h": "Ne yapar", "home.l1": "Bir cihaz bağlandığında veya bağlantısı kesildiğinde nerede olduğunuzu hatırlar ve haritada gösterir.", "home.l2": "24 saatlik rotanızı saklar, böylece adımlarınızı geri izleyebilirsiniz.", "home.l3": "Sinyal gücü, dokunsal geri bildirim ve isteğe bağlı AR / AirPods yön ipuçlarıyla sizi yakındaki cihaza yönlendirir.", "home.l4": "<b>Her şey iPhone’unuzda kalır.</b> Hesap yok, yükleme yok, analiz yok.", "priv.title": "Gizlilik Politikası", "priv.h1": "Özet", "priv.p1": "Blueee kişisel verileri toplamaz, yüklemez, satmaz ve paylaşmaz. Hesap, sunucu veya analiz/reklam SDK’sı yoktur. Tüm veriler iPhone’unuzda kalır.", "priv.h2": "Uygulamanın cihazınızda kullandığı veriler", "priv.loc": "<b>Konum</b> (izin verirseniz “Her Zaman” dahil): bir cihaz bağlandığında veya bağlantısı kesildiğinde nerede olduğunuzu kaydeder ve 24 saatlik rotayı tutar. Yerel olarak saklanır; eski noktalar otomatik silinir.", "priv.ble": "<b>Bluetooth</b>: eklediğiniz cihazlara bağlanır, arka planda bağlantı/kopmayı algılar ve sinyal gücünü okur. Adlar ve tanımlayıcılar yerel olarak saklanır.", "priv.cam": "<b>Kamera</b> (“Yürüyerek Bul”): ARKit, telefonunuzun yürüdüğü rotayı izler. Görüntüler anlık işlenir; asla fotoğraflanmaz, kaydedilmez veya yüklenmez.", "priv.mot": "<b>Hareket</b> (AirPods baş takibi): ses ipucunu yönlendirmek için anlık okunur; asla kaydedilmez veya yüklenmez.", "priv.h3": "Paylaşım ve saklama", "priv.p3": "Bu verilerin hiçbiri cihazınızdan çıkmaz; bu yüzden onlara erişemez, paylaşamaz veya satamayız. Uygulamayı silmek verilerini de siler. Herhangi bir izni iOS Ayarlar → Blueee’den geri alabilirsiniz.", "priv.h4": "Çocuklar", "priv.p4": "Blueee, çocuklar dahil kimseden bilerek veri toplamaz.", "priv.h5": "Değişiklikler ve iletişim", "priv.p5": "Bu politika değişirse aşağıdaki tarih güncellenir. Sorularınız için <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> adresinde bir issue açın.", "terms.title": "Kullanım Koşulları", "terms.h1": "Uygulamanın kullanımı", "terms.p1": "Blueee kişisel kullanım için ücretsiz sunulur. Kullanarak bu koşulları kabul etmiş olursunuz. Apple’ın standart Lisanslı Uygulama Son Kullanıcı Lisans Sözleşmesi de geçerlidir.", "terms.h2": "Cihazın bulunacağı garanti edilmez", "terms.p2": "Konum, Bluetooth sinyal gücü ve yön ipuçları tahmindir. Yanlış veya kullanılamaz olabilir (örneğin cihaz kapalıysa, menzil dışındaysa veya iOS arka plan etkinliğini sınırlıyorsa). Güvenlik açısından kritik veya yüksek değerli takip için Blueee’ye güvenmeyin.", "terms.h3": "Kabul edilebilir kullanım", "terms.p3": "Blueee’yi yalnızca size ait veya konumunu bulma izniniz olan cihazlarla kullanın; asla kişileri takip etmek için kullanmayın ve yerel yasalara uyun.", "terms.h4": "Garanti ve sorumluluk", "terms.p4": "Uygulama “olduğu gibi” sunulur, garanti verilmez. Yasaların izin verdiği ölçüde geliştirici, uygulamanın kullanımından kaynaklanan cihaz veya veri kaybından sorumlu değildir.", "terms.h5": "Değişiklikler", "terms.p5": "Bu koşullar güncellenebilir; kullanmaya devam etmek kabul anlamına gelir.", "sup.title": "Destek", "sup.h1": "Yardım alın", "sup.p1": "<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> adresinde iPhone modelinizi, iOS sürümünüzü ve ne olduğunu yazarak bir issue açın.", "sup.h2": "SSS", "sup.q1": "Neden “Her Zaman” konum izni istiyor?", "sup.a1": "Uygulama arka plandayken bir cihazın bağlantısı koptuğu anda nerede olduğunuzu kaydedebilmek için. “Uygulama Kullanılırken” de çalışır ancak arka plandaki kopmaları kaçırabilir.", "sup.q2": "Verilerim yükleniyor mu?", "sup.a2": "Hayır. Her şey iPhone’unuzda kalır. <a href=\"privacy.html\">Privacy Policy</a> sayfasına bakın.", "sup.q3": "Bir cihaz arka planda algılanmıyor.", "sup.a3": "Bluetooth’un açık olduğundan, Arka Planda Uygulama Yenileme’ye izin verildiğinden ve uygulamanın uygulama değiştiriciden zorla kapatılmadığından emin olun.", "foot": "© 2026 Blueee · Son güncelleme: 2026-11-09", "privacyLink": "Gizlilik Politikası"}, "id": {"name": "Bahasa Indonesia", "nav.home": "Beranda", "nav.privacy": "Privasi", "nav.terms": "Ketentuan", "nav.support": "Dukungan", "home.tag": "Temukan perangkat Bluetooth Anda: yang dekat, atau tempat terakhir Anda menaruhnya.", "home.h": "Fungsinya", "home.l1": "Mengingat di mana Anda berada saat perangkat tersambung atau terputus, lalu menampilkannya di peta.", "home.l2": "Menyimpan jejak 24 jam agar Anda bisa menelusuri kembali jalan Anda.", "home.l3": "Memandu Anda ke perangkat terdekat dengan kekuatan sinyal, haptik, dan petunjuk arah AR / AirPods opsional.", "home.l4": "<b>Semua tetap di iPhone Anda.</b> Tanpa akun, tanpa unggahan, tanpa analitik.", "priv.title": "Kebijakan Privasi", "priv.h1": "Ringkasan", "priv.p1": "Blueee tidak mengumpulkan, mengunggah, menjual, atau membagikan data pribadi. Tidak ada akun, server, maupun SDK analitik atau iklan. Semua data tersimpan di iPhone Anda.", "priv.h2": "Data yang digunakan aplikasi di perangkat Anda", "priv.loc": "<b>Lokasi</b> (termasuk “Selalu” jika Anda mengizinkan): mencatat di mana Anda berada saat perangkat tersambung atau terputus dan menyimpan jejak 24 jam. Disimpan secara lokal; titik lama dihapus otomatis.", "priv.ble": "<b>Bluetooth</b>: menyambung ke perangkat yang Anda tambahkan, mendeteksi sambung/putus di latar belakang, dan membaca kekuatan sinyal. Nama dan pengenal disimpan secara lokal.", "priv.cam": "<b>Kamera</b> (“Jalan untuk Menemukan”): ARKit melacak rute yang dilalui ponsel Anda. Gambar diproses langsung dan tidak pernah difoto, disimpan, atau diunggah.", "priv.mot": "<b>Gerakan</b> (pelacakan kepala AirPods): dibaca langsung untuk mengarahkan suara; tidak pernah disimpan atau diunggah.", "priv.h3": "Berbagi dan penyimpanan", "priv.p3": "Tidak ada data ini yang meninggalkan perangkat Anda, sehingga kami tidak dapat mengakses, membagikan, atau menjualnya. Menghapus aplikasi menghapus datanya. Anda dapat mencabut izin apa pun di Pengaturan iOS → Blueee.", "priv.h4": "Anak-anak", "priv.p4": "Blueee tidak dengan sengaja mengumpulkan data dari siapa pun, termasuk anak-anak.", "priv.h5": "Perubahan dan kontak", "priv.p5": "Jika kebijakan ini berubah, tanggal di bawah akan diperbarui. Pertanyaan: buka issue di <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Ketentuan Penggunaan", "terms.h1": "Penggunaan aplikasi", "terms.p1": "Blueee disediakan gratis untuk penggunaan pribadi. Dengan menggunakannya, Anda menyetujui ketentuan ini. Perjanjian Lisensi Pengguna Akhir Aplikasi Berlisensi standar Apple juga berlaku.", "terms.h2": "Tidak ada jaminan perangkat akan ditemukan", "terms.p2": "Lokasi, kekuatan sinyal Bluetooth, dan petunjuk arah hanyalah perkiraan. Bisa keliru atau tidak tersedia (misalnya saat perangkat mati, di luar jangkauan, atau iOS membatasi aktivitas latar belakang). Jangan mengandalkan Blueee untuk pelacakan yang kritis atau bernilai tinggi.", "terms.h3": "Penggunaan yang wajar", "terms.p3": "Gunakan Blueee hanya dengan perangkat milik Anda atau yang Anda izinkan untuk dilacak, jangan pernah untuk melacak orang, dan patuhi hukum setempat.", "terms.h4": "Jaminan dan tanggung jawab", "terms.p4": "Aplikasi disediakan “apa adanya” tanpa jaminan. Sejauh diizinkan hukum, pengembang tidak bertanggung jawab atas kehilangan atau kerusakan perangkat atau data akibat penggunaan aplikasi.", "terms.h5": "Perubahan", "terms.p5": "Ketentuan ini dapat diperbarui; melanjutkan penggunaan berarti menyetujuinya.", "sup.title": "Dukungan", "sup.h1": "Dapatkan bantuan", "sup.p1": "Buka issue di <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> dengan menyebutkan model iPhone, versi iOS, dan apa yang terjadi.", "sup.h2": "Pertanyaan umum", "sup.q1": "Mengapa meminta lokasi “Selalu”?", "sup.a1": "Agar dapat mencatat di mana Anda berada tepat saat perangkat terputus ketika aplikasi di latar belakang. “Saat Aplikasi Digunakan” juga berfungsi, tetapi bisa melewatkan pemutusan di latar belakang.", "sup.q2": "Apakah data saya diunggah?", "sup.a2": "Tidak. Semua tetap di iPhone Anda. Lihat <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Perangkat tidak terdeteksi di latar belakang.", "sup.a3": "Pastikan Bluetooth aktif, Penyegaran Aplikasi di Latar Belakang diizinkan, dan aplikasi tidak ditutup paksa dari pengalih aplikasi.", "foot": "© 2026 Blueee · Pembaruan terakhir: 2026-11-09", "privacyLink": "Kebijakan Privasi"}, "vi": {"name": "Tiếng Việt", "nav.home": "Trang chủ", "nav.privacy": "Quyền riêng tư", "nav.terms": "Điều khoản", "nav.support": "Hỗ trợ", "home.tag": "Tìm thiết bị Bluetooth của bạn: ở gần thì dẫn đường, thất lạc thì cho biết lần cuối ở đâu.", "home.h": "Ứng dụng làm được gì", "home.l1": "Ghi nhớ bạn đã ở đâu khi một thiết bị kết nối hoặc ngắt kết nối và hiển thị trên bản đồ.", "home.l2": "Lưu lộ trình 24 giờ để bạn có thể lần theo dấu chân mình.", "home.l3": "Dẫn bạn đến thiết bị ở gần bằng cường độ tín hiệu, phản hồi xúc giác và chỉ dẫn hướng AR / AirPods tùy chọn.", "home.l4": "<b>Mọi thứ ở lại trên iPhone của bạn.</b> Không tài khoản, không tải lên, không phân tích.", "priv.title": "Chính sách quyền riêng tư", "priv.h1": "Tóm tắt", "priv.p1": "Blueee không thu thập, tải lên, bán hay chia sẻ bất kỳ dữ liệu cá nhân nào. Không có tài khoản, máy chủ, hay SDK phân tích/quảng cáo. Toàn bộ dữ liệu nằm trên iPhone của bạn.", "priv.h2": "Dữ liệu ứng dụng dùng trên thiết bị của bạn", "priv.loc": "<b>Vị trí</b> (kể cả “Luôn luôn” nếu bạn cho phép): ghi lại bạn ở đâu khi thiết bị kết nối hoặc ngắt kết nối và giữ lộ trình 24 giờ. Lưu cục bộ; các điểm cũ tự động bị xóa.", "priv.ble": "<b>Bluetooth</b>: kết nối với các thiết bị bạn thêm, phát hiện kết nối/ngắt kết nối ở chế độ nền và đọc cường độ tín hiệu. Tên và mã định danh được lưu cục bộ.", "priv.cam": "<b>Camera</b> (“Đi bộ để định vị”): ARKit theo dõi lộ trình điện thoại đi qua. Hình ảnh được xử lý trực tiếp và không bao giờ được chụp, lưu hay tải lên.", "priv.mot": "<b>Chuyển động</b> (theo dõi đầu của AirPods): được đọc trực tiếp để điều hướng âm thanh; không bao giờ được lưu hay tải lên.", "priv.h3": "Chia sẻ và lưu giữ", "priv.p3": "Không dữ liệu nào rời khỏi thiết bị của bạn nên chúng tôi không thể truy cập, chia sẻ hay bán chúng. Xóa ứng dụng sẽ xóa dữ liệu của nó. Bạn có thể thu hồi mọi quyền trong Cài đặt iOS → Blueee.", "priv.h4": "Trẻ em", "priv.p4": "Blueee không cố ý thu thập dữ liệu của bất kỳ ai, kể cả trẻ em.", "priv.h5": "Thay đổi và liên hệ", "priv.p5": "Nếu chính sách này thay đổi, ngày bên dưới sẽ được cập nhật. Câu hỏi: hãy mở issue tại <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Điều khoản sử dụng", "terms.h1": "Sử dụng ứng dụng", "terms.p1": "Blueee được cung cấp miễn phí cho mục đích cá nhân. Khi sử dụng, bạn đồng ý với các điều khoản này. Thỏa thuận cấp phép người dùng cuối tiêu chuẩn của Apple cũng được áp dụng.", "terms.h2": "Không đảm bảo tìm được thiết bị", "terms.p2": "Vị trí, cường độ tín hiệu Bluetooth và chỉ dẫn hướng chỉ là ước tính. Chúng có thể sai hoặc không khả dụng (ví dụ khi thiết bị tắt, ngoài phạm vi, hoặc iOS hạn chế hoạt động nền). Đừng dựa vào Blueee cho việc theo dõi quan trọng về an toàn hoặc có giá trị cao.", "terms.h3": "Sử dụng hợp lệ", "terms.p3": "Chỉ dùng Blueee với thiết bị của bạn hoặc thiết bị bạn được phép định vị, không bao giờ dùng để theo dõi người khác, và tuân thủ pháp luật địa phương.", "terms.h4": "Bảo hành và trách nhiệm", "terms.p4": "Ứng dụng được cung cấp “nguyên trạng”, không có bảo hành. Trong phạm vi pháp luật cho phép, nhà phát triển không chịu trách nhiệm về việc mất hoặc hư hại thiết bị hay dữ liệu phát sinh từ việc sử dụng ứng dụng.", "terms.h5": "Thay đổi", "terms.p5": "Các điều khoản này có thể được cập nhật; tiếp tục sử dụng nghĩa là chấp nhận.", "sup.title": "Hỗ trợ", "sup.h1": "Nhận trợ giúp", "sup.p1": "Hãy mở issue tại <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>, ghi rõ mẫu iPhone, phiên bản iOS và sự cố xảy ra.", "sup.h2": "Câu hỏi thường gặp", "sup.q1": "Vì sao ứng dụng xin quyền vị trí “Luôn luôn”?", "sup.a1": "Để ghi lại bạn ở đâu vào lúc thiết bị ngắt kết nối khi ứng dụng đang chạy nền. “Khi dùng ứng dụng” cũng hoạt động nhưng có thể bỏ lỡ các lần ngắt kết nối ở chế độ nền.", "sup.q2": "Dữ liệu của tôi có được tải lên không?", "sup.a2": "Không. Mọi thứ ở lại trên iPhone của bạn. Xem <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Thiết bị không được phát hiện ở chế độ nền.", "sup.a3": "Hãy kiểm tra Bluetooth đang bật, Làm mới ứng dụng trong nền được cho phép và ứng dụng không bị buộc thoát từ trình chuyển đổi ứng dụng.", "foot": "© 2026 Blueee · Cập nhật lần cuối: 2026-11-09", "privacyLink": "Chính sách quyền riêng tư"}, "th": {"name": "ไทย", "nav.home": "หน้าแรก", "nav.privacy": "ความเป็นส่วนตัว", "nav.terms": "ข้อกำหนด", "nav.support": "ความช่วยเหลือ", "home.tag": "ค้นหาอุปกรณ์บลูทูธของคุณ ทั้งที่อยู่ใกล้ตัว หรือจุดที่เจอครั้งล่าสุด", "home.h": "ทำอะไรได้บ้าง", "home.l1": "จดจำว่าคุณอยู่ที่ไหนเมื่ออุปกรณ์เชื่อมต่อหรือตัดการเชื่อมต่อ และแสดงบนแผนที่", "home.l2": "เก็บเส้นทาง 24 ชั่วโมง เพื่อให้คุณย้อนรอยได้", "home.l3": "นำทางไปยังอุปกรณ์ใกล้ตัวด้วยความแรงสัญญาณ การสั่นตอบสนอง และคำแนะนำทิศทางแบบ AR / AirPods (ไม่บังคับ)", "home.l4": "<b>ทุกอย่างอยู่บน iPhone ของคุณเท่านั้น</b> ไม่ต้องมีบัญชี ไม่อัปโหลด ไม่มีการวิเคราะห์", "priv.title": "นโยบายความเป็นส่วนตัว", "priv.h1": "สรุป", "priv.p1": "Blueee ไม่เก็บรวบรวม อัปโหลด ขาย หรือแบ่งปันข้อมูลส่วนบุคคลใด ๆ ไม่มีบัญชี ไม่มีเซิร์ฟเวอร์ และไม่มี SDK วิเคราะห์หรือโฆษณา ข้อมูลทั้งหมดอยู่บน iPhone ของคุณ", "priv.h2": "ข้อมูลที่แอปใช้บนอุปกรณ์ของคุณ", "priv.loc": "<b>ตำแหน่ง</b> (รวมถึง “ตลอดเวลา” หากคุณอนุญาต): บันทึกว่าคุณอยู่ที่ไหนเมื่ออุปกรณ์เชื่อมต่อหรือตัดการเชื่อมต่อ และเก็บเส้นทาง 24 ชั่วโมง จัดเก็บในเครื่องเท่านั้น จุดเก่าจะถูกลบอัตโนมัติ", "priv.ble": "<b>บลูทูธ</b>: เชื่อมต่อกับอุปกรณ์ที่คุณเพิ่ม ตรวจจับการเชื่อมต่อ/ตัดการเชื่อมต่อในเบื้องหลัง และอ่านความแรงสัญญาณ ชื่อและตัวระบุจัดเก็บในเครื่องเท่านั้น", "priv.cam": "<b>กล้อง</b> (“เดินเพื่อค้นหา”): ARKit ติดตามเส้นทางที่โทรศัพท์ของคุณเดินผ่าน ภาพถูกประมวลผลแบบเรียลไทม์ และจะไม่ถูกถ่าย บันทึก หรืออัปโหลด", "priv.mot": "<b>การเคลื่อนไหว</b> (การติดตามศีรษะของ AirPods): อ่านแบบเรียลไทม์เพื่อปรับทิศทางเสียง ไม่มีการบันทึกหรืออัปโหลด", "priv.h3": "การแบ่งปันและการเก็บรักษา", "priv.p3": "ข้อมูลเหล่านี้ไม่ออกจากอุปกรณ์ของคุณ เราจึงเข้าถึง แบ่งปัน หรือขายไม่ได้ การลบแอปจะลบข้อมูลของแอปด้วย คุณสามารถเพิกถอนสิทธิ์ใด ๆ ได้ที่ การตั้งค่า iOS → Blueee", "priv.h4": "เด็ก", "priv.p4": "Blueee ไม่เก็บข้อมูลจากใครโดยเจตนา รวมถึงเด็ก", "priv.h5": "การเปลี่ยนแปลงและการติดต่อ", "priv.p5": "หากนโยบายนี้เปลี่ยนแปลง วันที่ด้านล่างจะได้รับการอัปเดต หากมีคำถาม โปรดเปิด issue ที่ <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>", "terms.title": "ข้อกำหนดการใช้งาน", "terms.h1": "การใช้แอป", "terms.p1": "Blueee ให้บริการฟรีสำหรับการใช้งานส่วนบุคคล การใช้งานถือว่าคุณยอมรับข้อกำหนดเหล่านี้ และข้อตกลงใบอนุญาตผู้ใช้ปลายทางมาตรฐานของ Apple สำหรับแอปที่ได้รับอนุญาตก็มีผลบังคับใช้ด้วย", "terms.h2": "ไม่รับประกันว่าจะพบอุปกรณ์", "terms.p2": "ตำแหน่ง ความแรงสัญญาณบลูทูธ และคำแนะนำทิศทางเป็นเพียงค่าประมาณ อาจไม่ถูกต้องหรือใช้งานไม่ได้ (เช่น อุปกรณ์ปิดอยู่ อยู่นอกระยะ หรือ iOS จำกัดการทำงานเบื้องหลัง) อย่าพึ่งพา Blueee สำหรับการติดตามที่เกี่ยวกับความปลอดภัยหรือมีมูลค่าสูง", "terms.h3": "การใช้งานที่เหมาะสม", "terms.p3": "ใช้ Blueee กับอุปกรณ์ที่เป็นของคุณหรือที่คุณได้รับอนุญาตให้ค้นหาเท่านั้น ห้ามใช้ติดตามบุคคล และปฏิบัติตามกฎหมายท้องถิ่น", "terms.h4": "การรับประกันและความรับผิด", "terms.p4": "แอปนี้ให้บริการ “ตามสภาพ” โดยไม่มีการรับประกันใด ๆ ตามขอบเขตที่กฎหมายอนุญาต ผู้พัฒนาไม่รับผิดชอบต่อการสูญหายหรือความเสียหายของอุปกรณ์หรือข้อมูลที่เกิดจากการใช้แอป", "terms.h5": "การเปลี่ยนแปลง", "terms.p5": "ข้อกำหนดเหล่านี้อาจมีการปรับปรุง การใช้งานต่อไปถือว่ายอมรับ", "sup.title": "ความช่วยเหลือ", "sup.h1": "ขอความช่วยเหลือ", "sup.p1": "เปิด issue ที่ <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> พร้อมระบุรุ่น iPhone เวอร์ชัน iOS และสิ่งที่เกิดขึ้น", "sup.h2": "คำถามที่พบบ่อย", "sup.q1": "ทำไมจึงขอสิทธิ์ตำแหน่ง “ตลอดเวลา”", "sup.a1": "เพื่อบันทึกว่าคุณอยู่ที่ไหนในขณะที่อุปกรณ์ตัดการเชื่อมต่อ ขณะที่แอปอยู่เบื้องหลัง ตัวเลือก “ขณะใช้แอป” ก็ใช้ได้ แต่อาจพลาดการตัดการเชื่อมต่อเบื้องหลัง", "sup.q2": "ข้อมูลของฉันถูกอัปโหลดหรือไม่", "sup.a2": "ไม่ ทุกอย่างอยู่บน iPhone ของคุณ ดู<a href=\"privacy.html\">Privacy Policy</a>", "sup.q3": "ตรวจไม่พบอุปกรณ์ในเบื้องหลัง", "sup.a3": "ตรวจสอบว่าเปิดบลูทูธอยู่ อนุญาต “การรีเฟรชแอปในเบื้องหลัง” และไม่ได้บังคับปิดแอปจากตัวสลับแอป", "foot": "© 2026 Blueee · อัปเดตล่าสุด: 2026-11-09", "privacyLink": "นโยบายความเป็นส่วนตัว"}, "pl": {"name": "Polski", "nav.home": "Start", "nav.privacy": "Prywatność", "nav.terms": "Warunki", "nav.support": "Pomoc", "home.tag": "Znajdź swoje urządzenia Bluetooth: w pobliżu albo tam, gdzie były ostatnio.", "home.h": "Co robi", "home.l1": "Zapamiętuje, gdzie byłeś, gdy urządzenie połączyło się lub rozłączyło, i pokazuje to na mapie.", "home.l2": "Przechowuje 24-godzinną trasę, abyś mógł wrócić po własnych śladach.", "home.l3": "Prowadzi do pobliskiego urządzenia dzięki sile sygnału, wibracjom i opcjonalnym wskazówkom kierunku w AR lub z AirPods.", "home.l4": "<b>Wszystko zostaje na Twoim iPhonie.</b> Bez konta, bez przesyłania, bez analityki.", "priv.title": "Polityka prywatności", "priv.h1": "Podsumowanie", "priv.p1": "Blueee nie zbiera, nie przesyła, nie sprzedaje ani nie udostępnia żadnych danych osobowych. Nie ma kont, serwerów ani SDK analitycznych czy reklamowych. Wszystkie dane są na Twoim iPhonie.", "priv.h2": "Dane używane przez aplikację na Twoim urządzeniu", "priv.loc": "<b>Lokalizacja</b> (także „Zawsze”, jeśli zezwolisz): zapisuje, gdzie byłeś, gdy urządzenie połączyło się lub rozłączyło, i przechowuje 24-godzinną trasę. Zapisywana lokalnie; starsze punkty są usuwane automatycznie.", "priv.ble": "<b>Bluetooth</b>: łączy się z dodanymi urządzeniami, wykrywa połączenie i rozłączenie w tle oraz odczytuje siłę sygnału. Nazwy i identyfikatory są zapisywane lokalnie.", "priv.cam": "<b>Aparat</b> („Idź, aby znaleźć”): ARKit śledzi trasę, którą pokonuje telefon. Obrazy są przetwarzane na żywo i nigdy nie są fotografowane, zapisywane ani przesyłane.", "priv.mot": "<b>Ruch</b> (śledzenie głowy w AirPods): odczytywany na żywo, aby kierować wskazówką dźwiękową; nigdy nie jest zapisywany ani przesyłany.", "priv.h3": "Udostępnianie i przechowywanie", "priv.p3": "Żadne z tych danych nie opuszczają Twojego urządzenia, więc nie możemy ich odczytać, udostępnić ani sprzedać. Usunięcie aplikacji usuwa jej dane. Dowolną zgodę możesz cofnąć w Ustawieniach iOS → Blueee.", "priv.h4": "Dzieci", "priv.p4": "Blueee świadomie nie zbiera danych od nikogo, także od dzieci.", "priv.h5": "Zmiany i kontakt", "priv.p5": "Jeśli ta polityka się zmieni, data poniżej zostanie zaktualizowana. Pytania: otwórz zgłoszenie na <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Warunki korzystania", "terms.h1": "Korzystanie z aplikacji", "terms.p1": "Blueee jest udostępniana bezpłatnie do użytku osobistego. Korzystając z niej, akceptujesz te warunki. Obowiązuje także standardowa umowa licencyjna Apple dla aplikacji licencjonowanych.", "terms.h2": "Brak gwarancji znalezienia urządzenia", "terms.p2": "Lokalizacja, siła sygnału Bluetooth i wskazówki kierunku to szacunki. Mogą być błędne lub niedostępne (np. gdy urządzenie jest wyłączone, poza zasięgiem albo iOS ogranicza działanie w tle). Nie polegaj na Blueee przy śledzeniu o krytycznym znaczeniu lub dużej wartości.", "terms.h3": "Dozwolone użycie", "terms.p3": "Używaj Blueee tylko z urządzeniami, które należą do Ciebie lub które możesz lokalizować; nigdy do śledzenia osób; przestrzegaj lokalnego prawa.", "terms.h4": "Gwarancja i odpowiedzialność", "terms.p4": "Aplikacja jest udostępniana „tak jak jest”, bez gwarancji. W zakresie dozwolonym prawem twórca nie odpowiada za utratę lub uszkodzenie urządzeń albo danych wynikające z używania aplikacji.", "terms.h5": "Zmiany", "terms.p5": "Warunki mogą być aktualizowane; dalsze korzystanie oznacza ich akceptację.", "sup.title": "Pomoc", "sup.h1": "Uzyskaj pomoc", "sup.p1": "Otwórz zgłoszenie na <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>, podając model iPhone’a, wersję iOS i opis problemu.", "sup.h2": "Najczęstsze pytania", "sup.q1": "Dlaczego aplikacja prosi o lokalizację „Zawsze”?", "sup.a1": "Aby zapisać, gdzie byłeś w chwili rozłączenia urządzenia, gdy aplikacja działa w tle. Opcja „Podczas używania” też działa, ale może pomijać rozłączenia w tle.", "sup.q2": "Czy moje dane są przesyłane?", "sup.a2": "Nie. Wszystko zostaje na Twoim iPhonie. Zobacz <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Urządzenie nie jest wykrywane w tle.", "sup.a3": "Upewnij się, że Bluetooth jest włączony, odświeżanie w tle jest dozwolone, a aplikacja nie została wymuszenie zamknięta w przełączniku aplikacji.", "foot": "© 2026 Blueee · Ostatnia aktualizacja: 2026-11-09", "privacyLink": "Polityka prywatności"}, "nl": {"name": "Nederlands", "nav.home": "Home", "nav.privacy": "Privacy", "nav.terms": "Voorwaarden", "nav.support": "Support", "home.tag": "Vind je Bluetooth-apparaten: dichtbij, of waar je ze voor het laatst had.", "home.h": "Wat het doet", "home.l1": "Onthoudt waar je was toen een apparaat verbond of de verbinding verbrak en toont dat op een kaart.", "home.l2": "Bewaart een route van 24 uur zodat je je stappen kunt terugvolgen.", "home.l3": "Leidt je naar een apparaat in de buurt met signaalsterkte, haptiek en optionele AR- of AirPods-richtingsaanwijzingen.", "home.l4": "<b>Alles blijft op je iPhone.</b> Geen account, geen upload, geen analyse.", "priv.title": "Privacybeleid", "priv.h1": "Samenvatting", "priv.p1": "Blueee verzamelt, uploadt, verkoopt of deelt geen persoonsgegevens. Er zijn geen accounts, geen servers en geen analyse- of advertentie-SDK’s. Alle gegevens blijven op je iPhone.", "priv.h2": "Gegevens die de app op je apparaat gebruikt", "priv.loc": "<b>Locatie</b> (inclusief “Altijd” als je dat toestaat): legt vast waar je was toen een apparaat verbond of de verbinding verbrak en bewaart een route van 24 uur. Lokaal opgeslagen; oudere punten worden automatisch verwijderd.", "priv.ble": "<b>Bluetooth</b>: verbindt met apparaten die je toevoegt, detecteert verbinden/verbreken op de achtergrond en leest de signaalsterkte. Namen en identificaties worden lokaal opgeslagen.", "priv.cam": "<b>Camera</b> (“Loop om te lokaliseren”): ARKit volgt de route die je telefoon aflegt. Beelden worden live verwerkt en nooit gefotografeerd, opgeslagen of geüpload.", "priv.mot": "<b>Beweging</b> (hoofdtracking van AirPods): live gelezen om de geluidsaanwijzing te sturen; nooit opgeslagen of geüpload.", "priv.h3": "Delen en bewaren", "priv.p3": "Geen van deze gegevens verlaat je apparaat, dus wij kunnen ze niet inzien, delen of verkopen. Als je de app verwijdert, worden de gegevens verwijderd. Je kunt elke toestemming intrekken via iOS-instellingen → Blueee.", "priv.h4": "Kinderen", "priv.p4": "Blueee verzamelt niet bewust gegevens van wie dan ook, ook niet van kinderen.", "priv.h5": "Wijzigingen en contact", "priv.p5": "Als dit beleid verandert, wordt de datum hieronder bijgewerkt. Vragen: open een issue op <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Gebruiksvoorwaarden", "terms.h1": "Gebruik van de app", "terms.p1": "Blueee wordt gratis aangeboden voor persoonlijk gebruik. Door de app te gebruiken ga je akkoord met deze voorwaarden. Ook de standaard licentieovereenkomst van Apple voor gelicentieerde apps is van toepassing.", "terms.h2": "Geen garantie dat een apparaat wordt gevonden", "terms.p2": "Locatie, Bluetooth-signaalsterkte en richtingsaanwijzingen zijn schattingen. Ze kunnen onjuist of niet beschikbaar zijn (bijvoorbeeld als een apparaat uit staat, buiten bereik is of iOS achtergrondactiviteit beperkt). Vertrouw niet op Blueee voor kritieke of waardevolle tracking.", "terms.h3": "Toegestaan gebruik", "terms.p3": "Gebruik Blueee alleen met apparaten die van jou zijn of die je mag lokaliseren, nooit om mensen te volgen, en houd je aan de lokale wetgeving.", "terms.h4": "Garantie en aansprakelijkheid", "terms.p4": "De app wordt aangeboden “zoals hij is”, zonder garanties. Voor zover wettelijk toegestaan is de ontwikkelaar niet aansprakelijk voor verlies of schade aan apparaten of gegevens door gebruik van de app.", "terms.h5": "Wijzigingen", "terms.p5": "Deze voorwaarden kunnen worden bijgewerkt; doorgaan met gebruik betekent acceptatie.", "sup.title": "Support", "sup.h1": "Hulp krijgen", "sup.p1": "Open een issue op <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> met je iPhone-model, iOS-versie en wat er gebeurde.", "sup.h2": "Veelgestelde vragen", "sup.q1": "Waarom vraagt de app om locatie “Altijd”?", "sup.a1": "Om vast te leggen waar je was op het moment dat een apparaat de verbinding verbreekt terwijl de app op de achtergrond draait. “Tijdens gebruik” werkt ook, maar kan verbrekingen op de achtergrond missen.", "sup.q2": "Worden mijn gegevens geüpload?", "sup.a2": "Nee. Alles blijft op je iPhone. Zie het <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Een apparaat wordt op de achtergrond niet gedetecteerd.", "sup.a3": "Controleer of Bluetooth aan staat, Ververs op achtergrond is toegestaan en de app niet geforceerd is afgesloten via de appkiezer.", "foot": "© 2026 Blueee · Laatst bijgewerkt: 2026-11-09", "privacyLink": "Privacybeleid"}, "uk": {"name": "Українська", "nav.home": "Головна", "nav.privacy": "Конфіденційність", "nav.terms": "Умови", "nav.support": "Підтримка", "home.tag": "Знаходьте свої Bluetooth-пристрої: поруч або там, де вони були востаннє.", "home.h": "Що вміє", "home.l1": "Запам’ятовує, де ви були, коли пристрій підключився або відключився, і показує це на карті.", "home.l2": "Зберігає маршрут за останні 24 години, щоб ви могли пройти своїми слідами.", "home.l3": "Веде до найближчого пристрою за рівнем сигналу, тактильним відгуком і, за бажанням, підказками напрямку через AR або AirPods.", "home.l4": "<b>Усе залишається на вашому iPhone.</b> Без облікового запису, без завантаження, без аналітики.", "priv.title": "Політика конфіденційності", "priv.h1": "Коротко", "priv.p1": "Blueee не збирає, не завантажує, не продає і не передає жодних персональних даних. У ньому немає облікових записів, серверів, аналітичних чи рекламних SDK. Усі дані зберігаються на вашому iPhone.", "priv.h2": "Які дані застосунок використовує на вашому пристрої", "priv.loc": "<b>Геолокація</b> (зокрема «Завжди», якщо ви дозволите): запам’ятовує, де ви були, коли пристрій підключився або відключився, і зберігає маршрут за 24 години. Зберігається локально; старі точки видаляються автоматично.", "priv.ble": "<b>Bluetooth</b>: підключається до доданих вами пристроїв, у фоні помічає підключення й відключення та зчитує рівень сигналу. Імена й ідентифікатори зберігаються локально.", "priv.cam": "<b>Камера</b> («Пройдіться, щоб знайти»): ARKit відстежує маршрут телефона. Зображення обробляються на льоту й ніколи не фотографуються, не зберігаються та не завантажуються.", "priv.mot": "<b>Рух</b> (відстеження голови в AirPods): зчитується на льоту для напрямку звуку; ніколи не зберігається й не завантажується.", "priv.h3": "Передавання та зберігання", "priv.p3": "Ці дані не залишають ваш пристрій, тому ми не маємо до них доступу й не можемо ними ділитися чи продавати їх. Видалення застосунку видаляє його дані. Будь-який дозвіл можна скасувати в Параметри iOS → Blueee.", "priv.h4": "Діти", "priv.p4": "Blueee свідомо не збирає даних ні від кого, зокрема від дітей.", "priv.h5": "Зміни та контакти", "priv.p5": "Якщо політика зміниться, дату нижче буде оновлено. Запитання: створіть issue на <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Умови використання", "terms.h1": "Використання застосунку", "terms.p1": "Blueee надається безкоштовно для особистого користування. Користуючись ним, ви погоджуєтеся з цими умовами. Також діє стандартна ліцензійна угода Apple для ліцензованих застосунків.", "terms.h2": "Немає гарантії, що пристрій буде знайдено", "terms.p2": "Місцеперебування, рівень сигналу Bluetooth і підказки напрямку — лише оцінки. Вони можуть бути хибними або недоступними (наприклад, якщо пристрій вимкнено, він поза зоною або iOS обмежує роботу у фоні). Не покладайтеся на Blueee для критично важливого чи дорогого відстеження.", "terms.h3": "Допустиме використання", "terms.p3": "Використовуйте Blueee лише з пристроями, які належать вам або які вам дозволено шукати, ніколи — для стеження за людьми, і дотримуйтеся місцевого законодавства.", "terms.h4": "Гарантії та відповідальність", "terms.p4": "Застосунок надається «як є», без гарантій. У межах, дозволених законом, розробник не відповідає за втрату чи пошкодження пристроїв або даних унаслідок використання застосунку.", "terms.h5": "Зміни", "terms.p5": "Умови можуть оновлюватися; подальше користування означає згоду.", "sup.title": "Підтримка", "sup.h1": "Отримати допомогу", "sup.p1": "Створіть issue на <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>, указавши модель iPhone, версію iOS і що сталося.", "sup.h2": "Поширені запитання", "sup.q1": "Навіщо потрібна геолокація «Завжди»?", "sup.a1": "Щоб зафіксувати, де ви були в момент відключення пристрою, коли застосунок працює у фоні. Варіант «Під час використання» теж працює, але може пропускати відключення у фоні.", "sup.q2": "Чи завантажуються мої дані?", "sup.a2": "Ні. Усе залишається на вашому iPhone. Див. <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Пристрій не виявляється у фоні.", "sup.a3": "Переконайтеся, що Bluetooth увімкнено, оновлення контенту у фоні дозволено, а застосунок не було примусово закрито в перемикачі застосунків.", "foot": "© 2026 Blueee · Останнє оновлення: 2026-11-09", "privacyLink": "Політика конфіденційності"}, "fa": {"name": "فارسی", "nav.home": "خانه", "nav.privacy": "حریم خصوصی", "nav.terms": "شرایط", "nav.support": "پشتیبانی", "home.tag": "دستگاه‌های بلوتوث خود را پیدا کنید: اگر نزدیک باشند راهنمایی می‌کند، اگر گم شوند آخرین جایشان را نشان می‌دهد.", "home.h": "چه کاری انجام می‌دهد", "home.l1": "به خاطر می‌سپارد وقتی دستگاهی وصل یا قطع شد کجا بودید و آن را روی نقشه نشان می‌دهد.", "home.l2": "مسیر ۲۴ ساعت اخیر را نگه می‌دارد تا بتوانید مسیر خود را دوباره دنبال کنید.", "home.l3": "با قدرت سیگنال، بازخورد لمسی و راهنمای اختیاری جهت با AR یا AirPods شما را به دستگاه نزدیک هدایت می‌کند.", "home.l4": "<b>همه‌چیز روی iPhone شما می‌ماند.</b> بدون حساب کاربری، بدون بارگذاری، بدون تحلیل.", "priv.title": "سیاست حریم خصوصی", "priv.h1": "خلاصه", "priv.p1": "Blueee هیچ داده شخصی‌ای را جمع‌آوری، بارگذاری، فروش یا به اشتراک نمی‌گذارد. حساب کاربری، سرور یا SDK تحلیل و تبلیغات وجود ندارد. همه داده‌ها روی iPhone شما می‌مانند.", "priv.h2": "داده‌هایی که برنامه روی دستگاه شما استفاده می‌کند", "priv.loc": "<b>مکان</b> (از جمله «همیشه» اگر اجازه دهید): ثبت می‌کند هنگام وصل یا قطع شدن دستگاه کجا بودید و مسیر ۲۴ ساعت اخیر را نگه می‌دارد. به‌صورت محلی ذخیره می‌شود؛ نقاط قدیمی خودکار حذف می‌شوند.", "priv.ble": "<b>بلوتوث</b>: به دستگاه‌هایی که اضافه می‌کنید وصل می‌شود، وصل و قطع شدن را در پس‌زمینه تشخیص می‌دهد و قدرت سیگنال را می‌خواند. نام‌ها و شناسه‌ها به‌صورت محلی ذخیره می‌شوند.", "priv.cam": "<b>دوربین</b> («برای پیدا کردن راه بروید»): ARKit مسیری را که گوشی طی می‌کند دنبال می‌کند. تصاویر هم‌زمان پردازش می‌شوند و هرگز عکس‌برداری، ذخیره یا بارگذاری نمی‌شوند.", "priv.mot": "<b>حرکت</b> (ردیابی سر در AirPods): برای هدایت صدا هم‌زمان خوانده می‌شود؛ هرگز ذخیره یا بارگذاری نمی‌شود.", "priv.h3": "اشتراک‌گذاری و نگهداری", "priv.p3": "هیچ‌یک از این داده‌ها دستگاه شما را ترک نمی‌کنند؛ بنابراین ما نمی‌توانیم به آن‌ها دسترسی داشته باشیم، به اشتراک بگذاریم یا بفروشیم. حذف برنامه داده‌های آن را هم حذف می‌کند. می‌توانید هر مجوزی را در تنظیمات iOS ← Blueee لغو کنید.", "priv.h4": "کودکان", "priv.p4": "Blueee آگاهانه از هیچ‌کس، از جمله کودکان، داده‌ای جمع‌آوری نمی‌کند.", "priv.h5": "تغییرات و تماس", "priv.p5": "اگر این سیاست تغییر کند، تاریخ زیر به‌روزرسانی می‌شود. برای پرسش‌ها در <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> یک issue باز کنید.", "terms.title": "شرایط استفاده", "terms.h1": "استفاده از برنامه", "terms.p1": "Blueee رایگان و برای استفاده شخصی ارائه می‌شود. با استفاده از آن، این شرایط را می‌پذیرید. توافق‌نامه استاندارد مجوز کاربر نهایی Apple برای برنامه‌های دارای مجوز نیز اعمال می‌شود.", "terms.h2": "تضمینی برای پیدا شدن دستگاه نیست", "terms.p2": "مکان، قدرت سیگنال بلوتوث و راهنمای جهت فقط تخمین هستند. ممکن است نادرست یا در دسترس نباشند (مثلاً وقتی دستگاه خاموش است، خارج از برد است یا iOS فعالیت پس‌زمینه را محدود می‌کند). برای ردیابی حیاتی یا پرارزش به Blueee تکیه نکنید.", "terms.h3": "استفاده مجاز", "terms.p3": "Blueee را فقط با دستگاه‌هایی استفاده کنید که مال خودتان است یا اجازه مکان‌یابی آن‌ها را دارید؛ هرگز برای ردیابی افراد؛ و قوانین محلی را رعایت کنید.", "terms.h4": "ضمانت و مسئولیت", "terms.p4": "برنامه «همان‌گونه که هست» و بدون هیچ ضمانتی ارائه می‌شود. تا حدی که قانون اجازه می‌دهد، توسعه‌دهنده مسئول از دست رفتن یا آسیب دستگاه یا داده‌ها در اثر استفاده از برنامه نیست.", "terms.h5": "تغییرات", "terms.p5": "این شرایط ممکن است به‌روزرسانی شود؛ ادامه استفاده به معنای پذیرش است.", "sup.title": "پشتیبانی", "sup.h1": "دریافت کمک", "sup.p1": "در <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> یک issue باز کنید و مدل iPhone، نسخه iOS و آنچه رخ داده را بنویسید.", "sup.h2": "پرسش‌های متداول", "sup.q1": "چرا مکان «همیشه» را می‌خواهد؟", "sup.a1": "تا وقتی برنامه در پس‌زمینه است، لحظه قطع شدن دستگاه مکان شما ثبت شود. گزینه «هنگام استفاده» هم کار می‌کند اما ممکن است قطع‌شدن‌های پس‌زمینه را از دست بدهد.", "sup.q2": "آیا داده‌های من بارگذاری می‌شوند؟", "sup.a2": "خیر. همه‌چیز روی iPhone شما می‌ماند. <a href=\"privacy.html\">Privacy Policy</a> را ببینید.", "sup.q3": "دستگاه در پس‌زمینه شناسایی نمی‌شود.", "sup.a3": "مطمئن شوید بلوتوث روشن است، «به‌روزرسانی پس‌زمینه برنامه» مجاز است و برنامه از تعویض‌کننده برنامه‌ها به‌اجبار بسته نشده است.", "foot": "© 2026 Blueee · آخرین به‌روزرسانی: 2026-11-09", "privacyLink": "سیاست حریم خصوصی"}, "he": {"name": "עברית", "nav.home": "בית", "nav.privacy": "פרטיות", "nav.terms": "תנאים", "nav.support": "תמיכה", "home.tag": "מצאו את מכשירי ה-Bluetooth שלכם: קרובים אליכם, או איפה שהיו בפעם האחרונה.", "home.h": "מה זה עושה", "home.l1": "זוכר איפה הייתם כשמכשיר התחבר או התנתק ומציג זאת על מפה.", "home.l2": "שומר מסלול של 24 שעות כדי שתוכלו לחזור על עקבותיכם.", "home.l3": "מוביל אתכם למכשיר קרוב באמצעות עוצמת האות, משוב haptic והכוונה אופציונלית ב-AR או ב-AirPods.", "home.l4": "<b>הכול נשאר ב-iPhone שלכם.</b> בלי חשבון, בלי העלאה, בלי ניתוח נתונים.", "priv.title": "מדיניות פרטיות", "priv.h1": "תקציר", "priv.p1": "Blueee אינה אוספת, מעלה, מוכרת או משתפת מידע אישי כלשהו. אין חשבונות, אין שרתים ואין SDK של ניתוח נתונים או פרסום. כל המידע נשאר ב-iPhone שלכם.", "priv.h2": "מידע שהאפליקציה משתמשת בו במכשיר שלכם", "priv.loc": "<b>מיקום</b> (כולל „תמיד” אם תאשרו): רושם איפה הייתם כשמכשיר התחבר או התנתק ושומר מסלול של 24 שעות. נשמר מקומית; נקודות ישנות נמחקות אוטומטית.", "priv.ble": "<b>Bluetooth</b>: מתחבר למכשירים שהוספתם, מזהה חיבור/ניתוק ברקע וקורא את עוצמת האות. שמות ומזהים נשמרים מקומית.", "priv.cam": "<b>מצלמה</b> („לכו כדי לאתר”): ARKit עוקב אחר המסלול שהטלפון עובר. התמונות מעובדות בזמן אמת ולעולם אינן מצולמות, נשמרות או מועלות.", "priv.mot": "<b>תנועה</b> (מעקב ראש ב-AirPods): נקרא בזמן אמת כדי לכוון את צליל ההכוונה; לעולם אינו נשמר או מועלה.", "priv.h3": "שיתוף ושמירה", "priv.p3": "אף אחד מהנתונים האלה אינו יוצא מהמכשיר שלכם, ולכן איננו יכולים לגשת אליהם, לשתף או למכור אותם. מחיקת האפליקציה מוחקת את הנתונים שלה. אפשר לבטל כל הרשאה ב הגדרות iOS ← Blueee.", "priv.h4": "ילדים", "priv.p4": "Blueee אינה אוספת ביודעין מידע מאף אחד, כולל ילדים.", "priv.h5": "שינויים ויצירת קשר", "priv.p5": "אם מדיניות זו תשתנה, התאריך שלמטה יעודכן. שאלות: פתחו issue ב-<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "תנאי שימוש", "terms.h1": "שימוש באפליקציה", "terms.p1": "Blueee ניתנת חינם לשימוש אישי. השימוש בה מהווה הסכמה לתנאים אלה. חל גם הסכם הרישיון הסטנדרטי של Apple למשתמש קצה באפליקציות מורשות.", "terms.h2": "אין הבטחה שמכשיר יימצא", "terms.p2": "מיקום, עוצמת אות Bluetooth והכוונת כיוון הם הערכות בלבד. הן עלולות להיות שגויות או לא זמינות (למשל כשהמכשיר כבוי, מחוץ לטווח, או ש-iOS מגביל פעילות ברקע). אל תסמכו על Blueee למעקב קריטי או יקר ערך.", "terms.h3": "שימוש מותר", "terms.p3": "השתמשו ב-Blueee רק עם מכשירים שבבעלותכם או שמותר לכם לאתר, לעולם לא למעקב אחר אנשים, ופעלו לפי החוק המקומי.", "terms.h4": "אחריות והגבלת אחריות", "terms.p4": "האפליקציה ניתנת „כפי שהיא” וללא אחריות. במידה המותרת בדין, המפתח אינו אחראי לאובדן או נזק למכשירים או לנתונים הנובעים משימוש באפליקציה.", "terms.h5": "שינויים", "terms.p5": "תנאים אלה עשויים להתעדכן; המשך שימוש מהווה הסכמה.", "sup.title": "תמיכה", "sup.h1": "קבלת עזרה", "sup.p1": "פתחו issue ב-<a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> וציינו את דגם ה-iPhone, גרסת ה-iOS ומה קרה.", "sup.h2": "שאלות נפוצות", "sup.q1": "למה מבקשים מיקום „תמיד”?", "sup.a1": "כדי לרשום איפה הייתם ברגע שמכשיר מתנתק בזמן שהאפליקציה ברקע. „בעת שימוש” עובד גם, אך עלול לפספס ניתוקים ברקע.", "sup.q2": "האם הנתונים שלי מועלים?", "sup.a2": "לא. הכול נשאר ב-iPhone שלכם. ראו <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "מכשיר לא מזוהה ברקע.", "sup.a3": "ודאו ש-Bluetooth פועל, שרענון אפליקציות ברקע מותר ושהאפליקציה לא נסגרה בכוח ממחליף האפליקציות.", "foot": "© 2026 Blueee · עודכן לאחרונה: 2026-11-09", "privacyLink": "מדיניות פרטיות"}, "ms": {"name": "Bahasa Melayu", "nav.home": "Utama", "nav.privacy": "Privasi", "nav.terms": "Terma", "nav.support": "Sokongan", "home.tag": "Cari peranti Bluetooth anda: yang berdekatan, atau tempat terakhir anda meletakkannya.", "home.h": "Fungsinya", "home.l1": "Mengingati di mana anda berada apabila peranti disambungkan atau diputuskan, dan memaparkannya pada peta.", "home.l2": "Menyimpan jejak 24 jam supaya anda boleh menjejak semula langkah anda.", "home.l3": "Memandu anda ke peranti berdekatan dengan kekuatan isyarat, haptik dan panduan arah AR / AirPods pilihan.", "home.l4": "<b>Semuanya kekal di iPhone anda.</b> Tiada akaun, tiada muat naik, tiada analitik.", "priv.title": "Dasar Privasi", "priv.h1": "Ringkasan", "priv.p1": "Blueee tidak mengumpul, memuat naik, menjual atau berkongsi sebarang data peribadi. Tiada akaun, pelayan, atau SDK analitik dan pengiklanan. Semua data kekal di iPhone anda.", "priv.h2": "Data yang digunakan aplikasi pada peranti anda", "priv.loc": "<b>Lokasi</b> (termasuk “Sentiasa” jika anda membenarkan): merekodkan di mana anda berada apabila peranti disambungkan atau diputuskan dan menyimpan jejak 24 jam. Disimpan secara setempat; titik lama dipadam secara automatik.", "priv.ble": "<b>Bluetooth</b>: menyambung ke peranti yang anda tambah, mengesan sambungan/pemutusan di latar belakang dan membaca kekuatan isyarat. Nama dan pengecam disimpan secara setempat.", "priv.cam": "<b>Kamera</b> (“Jalan untuk Mencari”): ARKit menjejak laluan yang dilalui telefon anda. Imej diproses secara langsung dan tidak pernah difoto, disimpan atau dimuat naik.", "priv.mot": "<b>Gerakan</b> (penjejakan kepala AirPods): dibaca secara langsung untuk mengarahkan bunyi; tidak pernah disimpan atau dimuat naik.", "priv.h3": "Perkongsian dan penyimpanan", "priv.p3": "Tiada data ini meninggalkan peranti anda, jadi kami tidak boleh mengakses, berkongsi atau menjualnya. Memadam aplikasi akan memadam datanya. Anda boleh menarik balik sebarang kebenaran dalam Tetapan iOS → Blueee.", "priv.h4": "Kanak-kanak", "priv.p4": "Blueee tidak dengan sengaja mengumpul data daripada sesiapa, termasuk kanak-kanak.", "priv.h5": "Perubahan dan hubungan", "priv.p5": "Jika dasar ini berubah, tarikh di bawah akan dikemas kini. Soalan: buka issue di <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Terma Penggunaan", "terms.h1": "Penggunaan aplikasi", "terms.p1": "Blueee disediakan percuma untuk kegunaan peribadi. Dengan menggunakannya, anda bersetuju dengan terma ini. Perjanjian Lesen Pengguna Akhir Aplikasi Berlesen standard Apple juga terpakai.", "terms.h2": "Tiada jaminan peranti akan ditemui", "terms.p2": "Lokasi, kekuatan isyarat Bluetooth dan panduan arah hanyalah anggaran. Ia boleh tidak tepat atau tidak tersedia (contohnya apabila peranti dimatikan, di luar jangkauan, atau iOS menghadkan aktiviti latar belakang). Jangan bergantung pada Blueee untuk penjejakan kritikal atau bernilai tinggi.", "terms.h3": "Penggunaan yang dibenarkan", "terms.p3": "Gunakan Blueee hanya dengan peranti milik anda atau yang anda dibenarkan mengesan, jangan sekali-kali untuk menjejak orang, dan patuhi undang-undang tempatan.", "terms.h4": "Waranti dan liabiliti", "terms.p4": "Aplikasi disediakan “seadanya” tanpa waranti. Setakat yang dibenarkan undang-undang, pembangun tidak bertanggungjawab atas kehilangan atau kerosakan peranti atau data akibat penggunaan aplikasi.", "terms.h5": "Perubahan", "terms.p5": "Terma ini boleh dikemas kini; terus menggunakan bermakna menerimanya.", "sup.title": "Sokongan", "sup.h1": "Dapatkan bantuan", "sup.p1": "Buka issue di <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> dengan menyatakan model iPhone, versi iOS dan apa yang berlaku.", "sup.h2": "Soalan lazim", "sup.q1": "Mengapa ia meminta lokasi “Sentiasa”?", "sup.a1": "Supaya dapat merekodkan di mana anda berada ketika peranti terputus semasa aplikasi di latar belakang. “Semasa Digunakan” juga berfungsi tetapi mungkin terlepas pemutusan di latar belakang.", "sup.q2": "Adakah data saya dimuat naik?", "sup.a2": "Tidak. Semuanya kekal di iPhone anda. Lihat <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Peranti tidak dikesan di latar belakang.", "sup.a3": "Pastikan Bluetooth dihidupkan, Segar Semula Aplikasi Latar Belakang dibenarkan dan aplikasi tidak ditutup secara paksa daripada penukar aplikasi.", "foot": "© 2026 Blueee · Dikemas kini: 2026-11-09", "privacyLink": "Dasar Privasi"}, "fil": {"name": "Filipino", "nav.home": "Home", "nav.privacy": "Privacy", "nav.terms": "Mga Tuntunin", "nav.support": "Suporta", "home.tag": "Hanapin ang iyong mga Bluetooth device: malapit sa iyo, o kung saan mo sila huling nakita.", "home.h": "Ano ang ginagawa nito", "home.l1": "Naaalala kung nasaan ka nang kumonekta o madiskonekta ang isang device, at ipinapakita ito sa mapa.", "home.l2": "Nagtatago ng 24-oras na ruta para masundan mo ulit ang dinaanan mo.", "home.l3": "Ginagabayan ka sa malapit na device gamit ang lakas ng signal, haptics, at opsyonal na gabay sa direksyon gamit ang AR / AirPods.", "home.l4": "<b>Lahat ay nananatili sa iyong iPhone.</b> Walang account, walang upload, walang analytics.", "priv.title": "Patakaran sa Privacy", "priv.h1": "Buod", "priv.p1": "Hindi kumokolekta, nag-a-upload, nagbebenta, o nagbabahagi ng anumang personal na data ang Blueee. Walang account, walang server, at walang analytics o advertising SDK. Ang lahat ng data ay nasa iyong iPhone.", "priv.h2": "Data na ginagamit ng app sa iyong device", "priv.loc": "<b>Lokasyon</b> (kasama ang “Palagi” kung papayagan mo): nire-record kung nasaan ka nang kumonekta o madiskonekta ang device at nagtatago ng 24-oras na ruta. Lokal na iniimbak; awtomatikong binubura ang mga lumang punto.", "priv.ble": "<b>Bluetooth</b>: kumokonekta sa mga device na idinagdag mo, nakakakita ng koneksyon/diskoneksyon sa background, at nagbabasa ng lakas ng signal. Lokal na iniimbak ang mga pangalan at identifier.", "priv.cam": "<b>Camera</b> (“Maglakad para Hanapin”): sinusubaybayan ng ARKit ang rutang nilalakaran ng telepono mo. Real-time na pinoproseso ang mga larawan at hindi kailanman kinukunan, sine-save, o ina-upload.", "priv.mot": "<b>Galaw</b> (head tracking ng AirPods): real-time na binabasa para gabayan ang tunog; hindi kailanman sine-save o ina-upload.", "priv.h3": "Pagbabahagi at pagtatago", "priv.p3": "Walang bahagi ng data na ito ang lumalabas sa iyong device, kaya hindi namin ito maa-access, maibabahagi, o maibebenta. Kapag binura ang app, buburahin din ang data nito. Maaari mong bawiin ang anumang pahintulot sa Mga Setting ng iOS → Blueee.", "priv.h4": "Mga bata", "priv.p4": "Hindi sadyang kumokolekta ng data ang Blueee mula kaninuman, kasama ang mga bata.", "priv.h5": "Mga pagbabago at pakikipag-ugnayan", "priv.p5": "Kung magbago ang patakarang ito, ia-update ang petsa sa ibaba. Mga tanong: magbukas ng issue sa <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Mga Tuntunin ng Paggamit", "terms.h1": "Paggamit ng app", "terms.p1": "Libre ang Blueee para sa personal na gamit. Sa paggamit nito, sumasang-ayon ka sa mga tuntuning ito. Nalalapat din ang karaniwang Licensed Application End User License Agreement ng Apple.", "terms.h2": "Walang garantiya na mahahanap ang device", "terms.p2": "Mga pagtatantya lamang ang lokasyon, lakas ng Bluetooth signal, at gabay sa direksyon. Maaaring mali o hindi available ang mga ito (halimbawa kapag naka-off ang device, wala sa saklaw, o nililimitahan ng iOS ang aktibidad sa background). Huwag umasa sa Blueee para sa kritikal o mahalagang pagsubaybay.", "terms.h3": "Katanggap-tanggap na paggamit", "terms.p3": "Gamitin ang Blueee sa mga device na pag-aari mo o may pahintulot kang hanapin lamang, hindi kailanman para sumubaybay ng tao, at sundin ang lokal na batas.", "terms.h4": "Warranty at pananagutan", "terms.p4": "Ibinibigay ang app nang “as is” nang walang warranty. Hanggang sa pinapayagan ng batas, hindi mananagot ang developer sa pagkawala o pinsala sa anumang device o data dahil sa paggamit ng app.", "terms.h5": "Mga pagbabago", "terms.p5": "Maaaring i-update ang mga tuntuning ito; ang patuloy na paggamit ay nangangahulugan ng pagtanggap.", "sup.title": "Suporta", "sup.h1": "Humingi ng tulong", "sup.p1": "Magbukas ng issue sa <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> kasama ang modelo ng iPhone, bersyon ng iOS, at kung ano ang nangyari.", "sup.h2": "Mga madalas itanong", "sup.q1": "Bakit hinihingi ang lokasyong “Palagi”?", "sup.a1": "Para ma-record kung nasaan ka sa sandaling madiskonekta ang device habang nasa background ang app. Gumagana rin ang “Habang Ginagamit” pero maaaring makaligtaan ang mga diskoneksyon sa background.", "sup.q2": "Ina-upload ba ang data ko?", "sup.a2": "Hindi. Lahat ay nananatili sa iyong iPhone. Tingnan ang <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Hindi natutukoy ang device sa background.", "sup.a3": "Tiyaking naka-on ang Bluetooth, pinapayagan ang Background App Refresh, at hindi sapilitang isinara ang app mula sa app switcher.", "foot": "© 2026 Blueee · Huling na-update: 2026-11-09", "privacyLink": "Patakaran sa Privacy"}, "cs": {"name": "Čeština", "nav.home": "Domů", "nav.privacy": "Soukromí", "nav.terms": "Podmínky", "nav.support": "Podpora", "home.tag": "Najděte svá zařízení Bluetooth: v blízkosti, nebo tam, kde jste je měli naposledy.", "home.h": "Co umí", "home.l1": "Zapamatuje si, kde jste byli, když se zařízení připojilo nebo odpojilo, a zobrazí to na mapě.", "home.l2": "Uchovává 24hodinovou trasu, abyste se mohli vrátit po svých stopách.", "home.l3": "Dovede vás k zařízení v blízkosti pomocí síly signálu, haptické odezvy a volitelných směrových nápověd v AR nebo s AirPods.", "home.l4": "<b>Všechno zůstává ve vašem iPhonu.</b> Žádný účet, žádné nahrávání, žádná analytika.", "priv.title": "Zásady ochrany soukromí", "priv.h1": "Shrnutí", "priv.p1": "Blueee neshromažďuje, nenahrává, neprodává ani nesdílí žádné osobní údaje. Neexistují účty, servery ani analytické či reklamní sady SDK. Všechna data zůstávají ve vašem iPhonu.", "priv.h2": "Data, která aplikace používá ve vašem zařízení", "priv.loc": "<b>Poloha</b> (včetně „Vždy“, pokud to povolíte): zaznamenává, kde jste byli, když se zařízení připojilo nebo odpojilo, a uchovává 24hodinovou trasu. Ukládá se lokálně; starší body se automaticky mažou.", "priv.ble": "<b>Bluetooth</b>: připojuje se k zařízením, která přidáte, na pozadí rozpozná připojení a odpojení a čte sílu signálu. Názvy a identifikátory se ukládají lokálně.", "priv.cam": "<b>Fotoaparát</b> („Jděte a najděte“): ARKit sleduje trasu, kterou telefon projde. Obraz se zpracovává naživo a nikdy se nefotí, neukládá ani nenahrává.", "priv.mot": "<b>Pohyb</b> (sledování hlavy u AirPods): čte se naživo pro směrování zvukové nápovědy; nikdy se neukládá ani nenahrává.", "priv.h3": "Sdílení a uchovávání", "priv.p3": "Žádná z těchto dat neopouští vaše zařízení, takže k nim nemáme přístup, nemůžeme je sdílet ani prodávat. Smazáním aplikace se smažou i její data. Jakékoli oprávnění můžete odvolat v Nastavení iOS → Blueee.", "priv.h4": "Děti", "priv.p4": "Blueee vědomě neshromažďuje data od nikoho, ani od dětí.", "priv.h5": "Změny a kontakt", "priv.p5": "Pokud se tyto zásady změní, aktualizuje se datum níže. Dotazy: otevřete issue na <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Podmínky používání", "terms.h1": "Používání aplikace", "terms.p1": "Blueee je poskytována zdarma pro osobní použití. Používáním souhlasíte s těmito podmínkami. Platí také standardní licenční smlouva Apple pro licencované aplikace.", "terms.h2": "Bez záruky nalezení zařízení", "terms.p2": "Poloha, síla signálu Bluetooth a směrové nápovědy jsou odhady. Mohou být nesprávné nebo nedostupné (například když je zařízení vypnuté, mimo dosah nebo iOS omezuje činnost na pozadí). Nespoléhejte na Blueee u kritického nebo cenného sledování.", "terms.h3": "Přípustné použití", "terms.p3": "Používejte Blueee jen se zařízeními, která vlastníte nebo která smíte lokalizovat, nikdy ke sledování osob, a dodržujte místní zákony.", "terms.h4": "Záruka a odpovědnost", "terms.p4": "Aplikace je poskytována „tak, jak je“, bez záruky. V rozsahu povoleném zákonem vývojář neodpovídá za ztrátu nebo poškození zařízení či dat vzniklé používáním aplikace.", "terms.h5": "Změny", "terms.p5": "Tyto podmínky mohou být aktualizovány; pokračováním v používání je přijímáte.", "sup.title": "Podpora", "sup.h1": "Získat pomoc", "sup.p1": "Otevřete issue na <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> s uvedením modelu iPhonu, verze iOS a toho, co se stalo.", "sup.h2": "Časté dotazy", "sup.q1": "Proč aplikace žádá o polohu „Vždy“?", "sup.a1": "Aby mohla zaznamenat, kde jste byli v okamžiku odpojení zařízení, když je aplikace na pozadí. „Při používání“ funguje také, ale může zmeškat odpojení na pozadí.", "sup.q2": "Nahrávají se moje data?", "sup.a2": "Ne. Všechno zůstává ve vašem iPhonu. Viz <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Zařízení se na pozadí nerozpozná.", "sup.a3": "Ujistěte se, že je zapnuté Bluetooth, povolená obnova aplikací na pozadí a aplikace nebyla násilně ukončena v přepínači aplikací.", "foot": "© 2026 Blueee · Naposledy aktualizováno: 2026-11-09", "privacyLink": "Zásady ochrany soukromí"}, "sv": {"name": "Svenska", "nav.home": "Hem", "nav.privacy": "Integritet", "nav.terms": "Villkor", "nav.support": "Support", "home.tag": "Hitta dina Bluetooth-enheter: i närheten, eller där du hade dem senast.", "home.h": "Vad den gör", "home.l1": "Kommer ihåg var du var när en enhet anslöts eller kopplades från och visar det på en karta.", "home.l2": "Sparar en 24-timmarsrutt så att du kan gå tillbaka i dina spår.", "home.l3": "Guidar dig till en enhet i närheten med signalstyrka, haptik och valfria riktningstips med AR eller AirPods.", "home.l4": "<b>Allt stannar på din iPhone.</b> Inget konto, ingen uppladdning, ingen analys.", "priv.title": "Integritetspolicy", "priv.h1": "Sammanfattning", "priv.p1": "Blueee samlar inte in, laddar inte upp, säljer eller delar några personuppgifter. Det finns inga konton, inga servrar och inga SDK:er för analys eller reklam. All data finns på din iPhone.", "priv.h2": "Data som appen använder på din enhet", "priv.loc": "<b>Plats</b> (inklusive ”Alltid” om du tillåter det): registrerar var du var när en enhet anslöts eller kopplades från och sparar en 24-timmarsrutt. Lagras lokalt; äldre punkter tas bort automatiskt.", "priv.ble": "<b>Bluetooth</b>: ansluter till enheter du lägger till, upptäcker anslutning/frånkoppling i bakgrunden och läser signalstyrka. Namn och identifierare lagras lokalt.", "priv.cam": "<b>Kamera</b> (”Gå för att hitta”): ARKit följer rutten som din telefon går. Bilder bearbetas direkt och fotograferas, sparas eller laddas aldrig upp.", "priv.mot": "<b>Rörelse</b> (huvudspårning i AirPods): läses direkt för att styra ljudsignalen; sparas eller laddas aldrig upp.", "priv.h3": "Delning och lagring", "priv.p3": "Ingen av dessa data lämnar din enhet, så vi kan varken komma åt, dela eller sälja dem. Om du tar bort appen tas dess data bort. Du kan återkalla alla behörigheter i iOS-inställningar → Blueee.", "priv.h4": "Barn", "priv.p4": "Blueee samlar inte medvetet in data från någon, inte heller från barn.", "priv.h5": "Ändringar och kontakt", "priv.p5": "Om policyn ändras uppdateras datumet nedan. Frågor: öppna ett ärende på <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Användarvillkor", "terms.h1": "Användning av appen", "terms.p1": "Blueee tillhandahålls gratis för personligt bruk. Genom att använda den godkänner du dessa villkor. Apples standardlicensavtal för licensierade appar gäller också.", "terms.h2": "Ingen garanti att hitta en enhet", "terms.p2": "Plats, Bluetooth-signalstyrka och riktningstips är uppskattningar. De kan vara fel eller otillgängliga (till exempel när en enhet är avstängd, utom räckhåll eller iOS begränsar bakgrundsaktivitet). Förlita dig inte på Blueee för kritisk eller värdefull spårning.", "terms.h3": "Tillåten användning", "terms.p3": "Använd Blueee endast med enheter du äger eller har tillstånd att lokalisera, aldrig för att spåra personer, och följ lokala lagar.", "terms.h4": "Garanti och ansvar", "terms.p4": "Appen tillhandahålls ”i befintligt skick” utan garantier. I den utsträckning lagen tillåter ansvarar utvecklaren inte för förlust av eller skada på enheter eller data till följd av användning av appen.", "terms.h5": "Ändringar", "terms.p5": "Dessa villkor kan uppdateras; fortsatt användning innebär godkännande.", "sup.title": "Support", "sup.h1": "Få hjälp", "sup.p1": "Öppna ett ärende på <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> med iPhone-modell, iOS-version och vad som hände.", "sup.h2": "Vanliga frågor", "sup.q1": "Varför ber appen om platsen ”Alltid”?", "sup.a1": "För att kunna registrera var du var i ögonblicket en enhet kopplas från medan appen är i bakgrunden. ”När appen används” fungerar också men kan missa frånkopplingar i bakgrunden.", "sup.q2": "Laddas min data upp?", "sup.a2": "Nej. Allt stannar på din iPhone. Se <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "En enhet upptäcks inte i bakgrunden.", "sup.a3": "Kontrollera att Bluetooth är på, att Uppdatera i bakgrunden är tillåtet och att appen inte tvångsavslutats i appväljaren.", "foot": "© 2026 Blueee · Senast uppdaterad: 2026-11-09", "privacyLink": "Integritetspolicy"}, "ro": {"name": "Română", "nav.home": "Acasă", "nav.privacy": "Confidențialitate", "nav.terms": "Termeni", "nav.support": "Asistență", "home.tag": "Găsiți-vă dispozitivele Bluetooth: aproape de dvs. sau unde le-ați avut ultima dată.", "home.h": "Ce face", "home.l1": "Reține unde erați când un dispozitiv s-a conectat sau deconectat și arată pe hartă.", "home.l2": "Păstrează un traseu de 24 de ore ca să vă puteți relua pașii.", "home.l3": "Vă ghidează către un dispozitiv din apropiere cu puterea semnalului, feedback haptic și indicații opționale de direcție prin AR sau AirPods.", "home.l4": "<b>Totul rămâne pe iPhone-ul dvs.</b> Fără cont, fără încărcare, fără analize.", "priv.title": "Politica de confidențialitate", "priv.h1": "Rezumat", "priv.p1": "Blueee nu colectează, nu încarcă, nu vinde și nu partajează date personale. Nu există conturi, servere sau SDK-uri de analiză ori publicitate. Toate datele rămân pe iPhone-ul dvs.", "priv.h2": "Datele pe care aplicația le folosește pe dispozitivul dvs.", "priv.loc": "<b>Locație</b> (inclusiv „Întotdeauna”, dacă permiteți): înregistrează unde erați când un dispozitiv s-a conectat sau deconectat și păstrează un traseu de 24 de ore. Stocată local; punctele vechi sunt șterse automat.", "priv.ble": "<b>Bluetooth</b>: se conectează la dispozitivele pe care le adăugați, detectează conectarea/deconectarea în fundal și citește puterea semnalului. Numele și identificatorii sunt stocate local.", "priv.cam": "<b>Cameră</b> („Mergi pentru a localiza”): ARKit urmărește traseul parcurs de telefon. Imaginile sunt procesate în direct și nu sunt niciodată fotografiate, salvate sau încărcate.", "priv.mot": "<b>Mișcare</b> (urmărirea capului la AirPods): citită în direct pentru a direcționa indiciul sonor; niciodată salvată sau încărcată.", "priv.h3": "Partajare și păstrare", "priv.p3": "Niciuna dintre aceste date nu părăsește dispozitivul dvs., deci nu le putem accesa, partaja sau vinde. Ștergerea aplicației îi șterge datele. Puteți revoca orice permisiune în Setări iOS → Blueee.", "priv.h4": "Copii", "priv.p4": "Blueee nu colectează cu bună știință date de la nimeni, inclusiv de la copii.", "priv.h5": "Modificări și contact", "priv.p5": "Dacă această politică se schimbă, data de mai jos va fi actualizată. Întrebări: deschideți un issue la <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Termeni de utilizare", "terms.h1": "Utilizarea aplicației", "terms.p1": "Blueee este oferită gratuit pentru uz personal. Folosind-o, acceptați acești termeni. Se aplică și contractul standard de licență Apple pentru aplicații licențiate.", "terms.h2": "Nicio garanție că dispozitivul va fi găsit", "terms.p2": "Locația, puterea semnalului Bluetooth și indicațiile de direcție sunt estimări. Pot fi greșite sau indisponibile (de exemplu când dispozitivul este oprit, în afara razei sau iOS limitează activitatea în fundal). Nu vă bazați pe Blueee pentru urmărire critică sau de mare valoare.", "terms.h3": "Utilizare acceptabilă", "terms.p3": "Folosiți Blueee doar cu dispozitive care vă aparțin sau pe care aveți permisiunea să le localizați, niciodată pentru a urmări persoane, și respectați legile locale.", "terms.h4": "Garanție și răspundere", "terms.p4": "Aplicația este oferită „ca atare”, fără garanții. În măsura permisă de lege, dezvoltatorul nu răspunde pentru pierderea sau deteriorarea dispozitivelor ori a datelor în urma utilizării aplicației.", "terms.h5": "Modificări", "terms.p5": "Acești termeni pot fi actualizați; continuarea utilizării înseamnă acceptare.", "sup.title": "Asistență", "sup.h1": "Obțineți ajutor", "sup.p1": "Deschideți un issue la <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> cu modelul de iPhone, versiunea iOS și ce s-a întâmplat.", "sup.h2": "Întrebări frecvente", "sup.q1": "De ce cere locația „Întotdeauna”?", "sup.a1": "Pentru a înregistra unde erați în momentul în care un dispozitiv se deconectează cât timp aplicația este în fundal. „În timpul utilizării” funcționează și el, dar poate pierde deconectările din fundal.", "sup.q2": "Datele mele sunt încărcate?", "sup.a2": "Nu. Totul rămâne pe iPhone-ul dvs. Consultați <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Un dispozitiv nu este detectat în fundal.", "sup.a3": "Verificați dacă Bluetooth este activat, dacă Reîmprospătarea aplicațiilor în fundal este permisă și dacă aplicația nu a fost închisă forțat din selectorul de aplicații.", "foot": "© 2026 Blueee · Ultima actualizare: 2026-11-09", "privacyLink": "Politica de confidențialitate"}, "el": {"name": "Ελληνικά", "nav.home": "Αρχική", "nav.privacy": "Απόρρητο", "nav.terms": "Όροι", "nav.support": "Υποστήριξη", "home.tag": "Βρείτε τις συσκευές Bluetooth σας: κοντά σας ή εκεί που τις είχατε τελευταία φορά.", "home.h": "Τι κάνει", "home.l1": "Θυμάται πού ήσασταν όταν μια συσκευή συνδέθηκε ή αποσυνδέθηκε και το δείχνει σε χάρτη.", "home.l2": "Κρατά μια διαδρομή 24 ωρών ώστε να ακολουθήσετε ξανά τα βήματά σας.", "home.l3": "Σας οδηγεί σε μια κοντινή συσκευή με την ισχύ του σήματος, απτική ανάδραση και προαιρετικές ενδείξεις κατεύθυνσης με AR ή AirPods.", "home.l4": "<b>Όλα μένουν στο iPhone σας.</b> Χωρίς λογαριασμό, χωρίς μεταφόρτωση, χωρίς αναλύσεις.", "priv.title": "Πολιτική απορρήτου", "priv.h1": "Περίληψη", "priv.p1": "Το Blueee δεν συλλέγει, δεν ανεβάζει, δεν πουλά και δεν μοιράζεται προσωπικά δεδομένα. Δεν υπάρχουν λογαριασμοί, διακομιστές ή SDK αναλύσεων και διαφημίσεων. Όλα τα δεδομένα μένουν στο iPhone σας.", "priv.h2": "Δεδομένα που χρησιμοποιεί η εφαρμογή στη συσκευή σας", "priv.loc": "<b>Τοποθεσία</b> (συμπεριλαμβανομένου του «Πάντα», αν το επιτρέψετε): καταγράφει πού ήσασταν όταν μια συσκευή συνδέθηκε ή αποσυνδέθηκε και κρατά διαδρομή 24 ωρών. Αποθηκεύεται τοπικά· τα παλαιότερα σημεία διαγράφονται αυτόματα.", "priv.ble": "<b>Bluetooth</b>: συνδέεται με τις συσκευές που προσθέτετε, εντοπίζει σύνδεση/αποσύνδεση στο παρασκήνιο και διαβάζει την ισχύ του σήματος. Τα ονόματα και τα αναγνωριστικά αποθηκεύονται τοπικά.", "priv.cam": "<b>Κάμερα</b> («Περπατήστε για εντοπισμό»): το ARKit παρακολουθεί τη διαδρομή που διανύει το τηλέφωνό σας. Οι εικόνες επεξεργάζονται σε πραγματικό χρόνο και δεν φωτογραφίζονται, δεν αποθηκεύονται και δεν ανεβαίνουν ποτέ.", "priv.mot": "<b>Κίνηση</b> (παρακολούθηση κεφαλής AirPods): διαβάζεται σε πραγματικό χρόνο για να κατευθύνει τον ήχο· δεν αποθηκεύεται ούτε ανεβαίνει ποτέ.", "priv.h3": "Κοινοποίηση και διατήρηση", "priv.p3": "Κανένα από αυτά τα δεδομένα δεν φεύγει από τη συσκευή σας, επομένως δεν μπορούμε να τα δούμε, να τα μοιραστούμε ή να τα πουλήσουμε. Η διαγραφή της εφαρμογής διαγράφει τα δεδομένα της. Μπορείτε να ανακαλέσετε οποιαδήποτε άδεια στις Ρυθμίσεις iOS → Blueee.", "priv.h4": "Παιδιά", "priv.p4": "Το Blueee δεν συλλέγει εν γνώσει του δεδομένα από κανέναν, συμπεριλαμβανομένων των παιδιών.", "priv.h5": "Αλλαγές και επικοινωνία", "priv.p5": "Αν αλλάξει αυτή η πολιτική, η ημερομηνία παρακάτω θα ενημερωθεί. Ερωτήσεις: ανοίξτε ένα issue στο <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a>.", "terms.title": "Όροι χρήσης", "terms.h1": "Χρήση της εφαρμογής", "terms.p1": "Το Blueee παρέχεται δωρεάν για προσωπική χρήση. Χρησιμοποιώντας το, αποδέχεστε αυτούς τους όρους. Ισχύει επίσης η τυπική Άδεια Χρήσης Τελικού Χρήστη της Apple για εφαρμογές με άδεια.", "terms.h2": "Καμία εγγύηση ότι θα βρεθεί η συσκευή", "terms.p2": "Η τοποθεσία, η ισχύς του σήματος Bluetooth και οι ενδείξεις κατεύθυνσης είναι εκτιμήσεις. Μπορεί να είναι λανθασμένες ή μη διαθέσιμες (π.χ. όταν η συσκευή είναι απενεργοποιημένη, εκτός εμβέλειας ή το iOS περιορίζει τη δραστηριότητα στο παρασκήνιο). Μην βασίζεστε στο Blueee για κρίσιμη ή υψηλής αξίας παρακολούθηση.", "terms.h3": "Αποδεκτή χρήση", "terms.p3": "Χρησιμοποιήστε το Blueee μόνο με συσκευές που σας ανήκουν ή που έχετε άδεια να εντοπίσετε, ποτέ για την παρακολούθηση ατόμων, και τηρήστε τους τοπικούς νόμους.", "terms.h4": "Εγγύηση και ευθύνη", "terms.p4": "Η εφαρμογή παρέχεται «ως έχει», χωρίς εγγυήσεις. Στον βαθμό που επιτρέπεται από το νόμο, ο προγραμματιστής δεν ευθύνεται για απώλεια ή ζημιά σε συσκευές ή δεδομένα που προκύπτει από τη χρήση της εφαρμογής.", "terms.h5": "Αλλαγές", "terms.p5": "Οι όροι αυτοί ενδέχεται να ενημερώνονται· η συνέχιση της χρήσης σημαίνει αποδοχή.", "sup.title": "Υποστήριξη", "sup.h1": "Λάβετε βοήθεια", "sup.p1": "Ανοίξτε ένα issue στο <a href=\"https://github.com/whlan02/blueee/issues\">github.com/whlan02/blueee/issues</a> αναφέροντας το μοντέλο του iPhone, την έκδοση iOS και τι συνέβη.", "sup.h2": "Συχνές ερωτήσεις", "sup.q1": "Γιατί ζητά τοποθεσία «Πάντα»;", "sup.a1": "Για να καταγράψει πού ήσασταν τη στιγμή που μια συσκευή αποσυνδέεται ενώ η εφαρμογή βρίσκεται στο παρασκήνιο. Το «Κατά τη χρήση» λειτουργεί επίσης, αλλά μπορεί να χάσει αποσυνδέσεις στο παρασκήνιο.", "sup.q2": "Ανεβαίνουν τα δεδομένα μου;", "sup.a2": "Όχι. Όλα μένουν στο iPhone σας. Δείτε την <a href=\"privacy.html\">Privacy Policy</a>.", "sup.q3": "Μια συσκευή δεν εντοπίζεται στο παρασκήνιο.", "sup.a3": "Βεβαιωθείτε ότι το Bluetooth είναι ενεργό, η Ανανέωση εφαρμογών στο παρασκήνιο επιτρέπεται και η εφαρμογή δεν έχει κλείσει αναγκαστικά από τον εναλλάκτη εφαρμογών.", "foot": "© 2026 Blueee · Τελευταία ενημέρωση: 2026-11-09", "privacyLink": "Πολιτική απορρήτου"}};
var RTL=["ar", "ur", "fa", "he"];
(function () {
  var KEY = 'blueee-lang', select = document.getElementById('lang');
  var fromUrl = new URLSearchParams(location.search).get('lang');
  function saved() { try { return localStorage.getItem(KEY); } catch (e) { return null; } }
  var lang = [fromUrl, saved()].find(function (c) { return c && T[c]; }) || 'en';
  function apply(code) {
    var d = T[code];
    document.documentElement.lang = code === 'zh' ? 'zh-Hans' : code;
    document.documentElement.dir = RTL.indexOf(code) >= 0 ? 'rtl' : 'ltr';
    document.querySelectorAll('[data-i18n]').forEach(function (e) {
      var v = d[e.dataset.i18n]; if (v != null) e.innerHTML = v;
    });
    var h1 = document.querySelector('h1');
    document.title = (h1 ? h1.textContent : 'Blueee') + ' – Blueee';
    select.value = code;
  }
  select.addEventListener('change', function () {
    try { localStorage.setItem(KEY, select.value); } catch (e) {}
    apply(select.value);
  });
  apply(lang);
})();
